window.QBANK = window.QBANK || {};
window.QBANK["sma-bahasa-indonesia"] = {
  level: "SMA", subject: "Bahasa Indonesia", duration: 900,
  questions: [
    { q: "Kata berimbuhan me- + kata dasar sapu yang benar adalah ...", options: ["mensapu", "menyapu", "menysapu", "menyapukan"], answer: 1, solution: "Langkah 1: kata dasar sapu diawali huruf s. Langkah 2: kaidah morfologi, imbuhan me- bertemu dengan awal s, p, t, k umumnya luluh menjadi meny-, mem-, men-, meng-. Langkah 3: jadi bentuk bakunya adalah menyapu." },
    { q: "Manakah kalimat berikut yang efektif?", options: ["Para siswa-siswa sedang mengikuti ujian.", "Siswa-siswa para sedang mengikuti ujian.", "Para siswa sedang mengikuti ujian.", "Para siswa mengikuti sedang ujian."], answer: 2, solution: "Langkah 1: kalimat efektif menghindari penanda jamak yang ganda. Langkah 2: kata para sudah menunjukkan jamak, sehingga siswa-siswa tidak diperlukan lagi. Langkah 3: kalimat yang tepat dan efektif adalah Para siswa sedang mengikuti ujian." },
    { q: "Perhatikan kalimat: Wajahnya bersinar bagaikan rembulan. Majas yang digunakan adalah ...", options: ["metafora", "personifikasi", "hiperbola", "perumpamaan (simile)"], answer: 3, solution: "Langkah 1: perhatikan kata pembanding bagaikan pada kalimat. Langkah 2: majas yang membandingkan dua hal dengan kata seperti, bagaikan, laksana, atau sebagai disebut perumpamaan (simile). Langkah 3: jadi majasnya adalah perumpamaan." },
    { q: "Antonim kata dermawan adalah ...", options: ["kikir", "baik hati", "murah hati", "ramah"], answer: 0, solution: "Langkah 1: dermawan artinya suka memberi atau tidak pelit. Langkah 2: antonim adalah lawan kata, jadi cari kata yang bermakna pelit. Langkah 3: kikir bersinonim dengan pelit, sehingga menjadi antonim yang tepat." },
    { q: "Sinonim kata bahagia adalah ...", options: ["sedih", "gembira", "kecewa", "marah"], answer: 1, solution: "Langkah 1: bahagia artinya merasa senang atau sukacita. Langkah 2: sinonim adalah persamaan kata, jadi cari kata yang maknanya paling dekat. Langkah 3: gembira memiliki makna yang sama dengan bahagia." },
    { q: "Penulisan kata berikut yang benar menurut kaidah bahasa Indonesia adalah ...", options: ["apotik", "afotek", "apotek", "apothek"], answer: 2, solution: "Langkah 1: kata ini merupakan serapan dari bahasa Belanda apotheek. Langkah 2: menurut KBBI, bentuk bakunya ditulis apotek. Langkah 3: bentuk apotik adalah penulisan yang tidak baku." },
    { q: "Berikut ini yang BUKAN unsur intrinsik cerpen adalah ...", options: ["tema", "tokoh dan penokohan", "latar", "latar belakang pengarang"], answer: 3, solution: "Langkah 1: unsur intrinsik adalah unsur yang berasal dari dalam karya sastra itu sendiri. Langkah 2: tema, tokoh dan penokohan, serta latar termasuk unsur intrinsik. Langkah 3: latar belakang pengarang berasal dari luar karya, sehingga termasuk unsur ekstrinsik." },
    { q: "Dalam sebuah pantun, sampiran terletak pada ...", options: ["baris ke-1 dan ke-2", "baris ke-3 dan ke-4", "baris ke-2 dan ke-3", "seluruh baris"], answer: 0, solution: "Langkah 1: pantun terdiri atas empat baris sebait. Langkah 2: dua baris pertama disebut sampiran, dua baris terakhir disebut isi. Langkah 3: jadi sampiran terletak pada baris ke-1 dan ke-2." },
    { q: "Kata baku dari kata serapan bahasa Inggris schedule adalah ...", options: ["jadual", "jadwal", "zedwal", "jadfal"], answer: 1, solution: "Langkah 1: kata ini diserap dari bahasa Inggris schedule. Langkah 2: menurut KBBI, bentuk bakunya adalah jadwal. Langkah 3: bentuk jadual tidak baku." },
    { q: "Perhatikan kalimat: Meskipun hujan deras, ia tetap berangkat. Kata meskipun termasuk konjungsi ...", options: ["koordinatif", "korelatif", "subordinatif", "antarkalimat"], answer: 2, solution: "Langkah 1: kata meskipun menghubungkan anak kalimat dengan induk kalimat yang bertingkat. Langkah 2: konjungsi yang menghubungkan klausa bertingkat disebut konjungsi subordinatif. Langkah 3: meskipun menyatakan makna konsesi (perlawanan), jadi termasuk subordinatif." },
    { q: "Perhatikan struktur teks anekdot berikut: abstrak, orientasi, krisis, reaksi, koda. Bagian yang berisi puncak permasalahan atau kekonyolan cerita disebut ...", options: ["abstrak", "orientasi", "krisis", "koda"], answer: 2, solution: "Langkah 1: ingat urutan struktur teks anekdot. Langkah 2: krisis adalah bagian yang memuat puncak masalah atau kejadian lucu yang menjadi inti sindiran. Langkah 3: jadi jawabannya krisis. (Abstrak = pembuka opsional, orientasi = latar, koda = penutup.)" },
    { q: "Kata 'syahdan', 'hatta', dan 'sebermula' yang sering muncul dalam hikayat termasuk ...", options: ["kata arkais", "kata serapan", "kata ulang", "kata kerja"], answer: 0, solution: "Langkah 1: kata-kata tersebut sudah jarang dipakai dalam bahasa Indonesia modern. Langkah 2: kata kuno yang tidak lagi lazim digunakan disebut kata arkais. Langkah 3: jadi jawabannya kata arkais." },
    { q: "Tujuan utama teks negosiasi adalah ...", options: ["meyakinkan pembaca agar membeli suatu produk", "menceritakan pengalaman pribadi penulis", "menjelaskan langkah-langkah melakukan sesuatu", "mencapai kesepakatan yang menguntungkan kedua belah pihak"], answer: 3, solution: "Langkah 1: negosiasi adalah proses tawar-menawar antara dua pihak. Langkah 2: tujuannya agar kedua pihak sepakat dan sama-sama diuntungkan (win-win solution). Langkah 3: jadi jawabannya mencapai kesepakatan yang menguntungkan kedua belah pihak." },
    { q: "Teks riwayat hidup seseorang yang ditulis oleh tokoh itu sendiri disebut ...", options: ["biografi", "anekdot", "autobiografi", "hikayat"], answer: 2, solution: "Langkah 1: biografi ditulis oleh orang lain tentang seorang tokoh. Langkah 2: jika ditulis oleh tokoh itu sendiri tentang dirinya, disebut autobiografi (auto = sendiri). Langkah 3: jadi jawabannya autobiografi." },
    { q: "Manakah kalimat berikut yang TIDAK efektif karena mengandung pleonasme (pemborosan kata)?", options: ["Ia memasuki kelas pagi ini.", "Ia masuk ke dalam kelas pagi ini.", "Mereka pulang setelah rapat selesai.", "Adik menangis karena mainannya rusak."], answer: 1, solution: "Langkah 1: pleonasme adalah pemakaian kata yang maknanya sudah terkandung dalam kata lain. Langkah 2: kata masuk sudah berarti pergi ke dalam, sehingga frasa ke dalam menjadi mubazir. Langkah 3: jadi kalimat yang tidak efektif adalah 'Ia masuk ke dalam kelas pagi ini'." },
    { q: "Amanat atau pesan moral yang ingin disampaikan pengarang melalui cerpen termasuk unsur ...", options: ["intrinsik", "ekstrinsik", "kebahasaan", "struktur"], answer: 1, solution: "Langkah 1: amanat adalah nilai atau pesan yang terkandung dalam cerita. Langkah 2: unsur ekstrinsik adalah unsur dari luar karya, seperti nilai moral, sosial, dan budaya yang melatarinya. Langkah 3: jadi amanat termasuk unsur ekstrinsik." },
    { q: "Frasa 'oleh karena itu' yang menghubungkan dua kalimat termasuk konjungsi ...", options: ["intrakalimat", "antarkalimat", "subordinatif", "korelatif"], answer: 1, solution: "Langkah 1: perhatikan bahwa 'oleh karena itu' menghubungkan kalimat dengan kalimat (ditulis setelah titik). Langkah 2: konjungsi yang menghubungkan dua kalimat disebut konjungsi antarkalimat. Langkah 3: jadi jawabannya antarkalimat." },
    { q: "Perhatikan kalimat: Angin malam berbisik lembut di telingaku. Majas yang digunakan adalah ...", options: ["personifikasi", "metafora", "hiperbola", "ironi"], answer: 0, solution: "Langkah 1: angin adalah benda mati yang digambarkan bisa berbisik seperti manusia. Langkah 2: majas yang memberikan sifat manusia kepada benda mati disebut personifikasi. Langkah 3: jadi majasnya personifikasi." },
    { q: "Penulisan kata berikut yang baku adalah ...", options: ["nasehat", "nasihat", "naseihat", "nashihat"], answer: 1, solution: "Langkah 1: kata ini sering salah ditulis dengan huruf e. Langkah 2: menurut KBBI, bentuk bakunya adalah nasihat. Langkah 3: jadi penulisan yang benar adalah nasihat." },
    { q: "Bentuk pasif yang tepat dari kalimat 'Ibu memasak nasi' adalah ...", options: ["Nasi dimasak ibu.", "Nasi memasak ibu.", "Ibu dimasak nasi.", "Nasi dimasaki ibu."], answer: 0, solution: "Langkah 1: ubah kalimat aktif menjadi pasif dengan memindahkan objek menjadi subjek. Langkah 2: predikat aktif memasak (awalan me-) berubah menjadi pasif dimasak (awalan di-). Langkah 3: jadi bentuk pasifnya adalah 'Nasi dimasak ibu'." },
    { q: "Ciri utama teks anekdot adalah ...", options: ["menyampaikan kritik atau sindiran yang dibalut humor", "menyajikan data dan fakta ilmiah secara objektif", "menceritakan kembali kejadian secara kronologis", "memberikan petunjuk melakukan sesuatu"], answer: 0, solution: "Langkah 1: anekdot adalah cerita singkat yang lucu dan menggelitik. Langkah 2: kelucuan itu dipakai sebagai bungkus untuk menyampaikan kritik atau sindiran terhadap suatu keadaan. Langkah 3: jadi ciri utamanya menyampaikan kritik atau sindiran yang dibalut humor." },
    { q: "Hikayat disebut bersifat istanasentris karena ...", options: ["pengarangnya pasti seorang raja", "ceritanya hanya boleh dibaca di lingkungan istana", "seluruh isinya menceritakan perang antar kerajaan", "latar dan tokoh ceritanya berkaitan dengan kehidupan istana atau kerajaan"], answer: 3, solution: "Langkah 1: istanasentris berasal dari kata istana dan sentris (berpusat). Langkah 2: artinya cerita berpusat pada kehidupan di sekitar istana atau kerajaan. Langkah 3: jadi jawabannya latar dan tokoh ceritanya berkaitan dengan kehidupan istana atau kerajaan." },
    { q: "Dalam struktur teks negosiasi, bagian yang berisi kegiatan tawar-menawar disebut ...", options: ["orientasi", "pengajuan", "penawaran", "persetujuan"], answer: 2, solution: "Langkah 1: ingat urutan struktur negosiasi: orientasi, pengajuan, penawaran, persetujuan, penutup. Langkah 2: tawar-menawar terjadi pada tahap penawaran, saat kedua pihak saling mengajukan harga atau syarat. Langkah 3: jadi jawabannya penawaran." },
    { q: "Bagian teks biografi yang berisi komentar atau pandangan penulis terhadap tokoh yang diceritakan disebut ...", options: ["orientasi", "krisis", "reorientasi", "abstrak"], answer: 2, solution: "Langkah 1: struktur teks biografi terdiri atas orientasi, peristiwa penting, dan reorientasi. Langkah 2: reorientasi adalah bagian penutup yang berisi simpulan, komentar, atau pandangan penulis tentang tokoh. Langkah 3: jadi jawabannya reorientasi." },
    { q: "Perhatikan kalimat: Ia rajin belajar sehingga lulus dengan nilai terbaik. Kata 'sehingga' menunjukkan hubungan makna ...", options: ["syarat", "akibat", "tujuan", "perbandingan"], answer: 1, solution: "Langkah 1: 'rajin belajar' adalah penyebab, sedangkan 'lulus dengan nilai terbaik' adalah hasilnya. Langkah 2: konjungsi sehingga menghubungkan sebab dengan akibat. Langkah 3: jadi hubungan maknanya adalah akibat." },
    { q: "Penulisan huruf kapital yang tepat terdapat pada kalimat ...", options: ["Bulan agustus adalah bulan kemerdekaan.", "Hari senin upacara bendera dilaksanakan.", "Kota Surabaya terletak di Jawa Timur.", "Bahasa indonesia bahasa persatuan."], answer: 2, solution: "Langkah 1: nama bulan, nama hari, dan nama bahasa adalah nama diri sehingga huruf awalnya kapital: Agustus, Senin, Indonesia. Langkah 2: pilihan pertama, kedua, dan keempat salah karena huruf awalnya kecil. Langkah 3: hanya 'Kota Surabaya terletak di Jawa Timur' yang penulisannya sudah tepat." },
    { q: "Penulisan yang tepat untuk kata depan 'di' yang diikuti kata tanya adalah ...", options: ["di mana", "dimana", "di-mana", "diMana"], answer: 0, solution: "Langkah 1: 'di' sebagai kata depan yang menunjukkan tempat ditulis terpisah dari kata yang mengikutinya. Langkah 2: 'mana' di sini berfungsi sebagai kata tanya tempat, bukan imbuhan. Langkah 3: jadi penulisan yang tepat adalah 'di mana'." },
    { q: "Cerpen yang memakai kata 'aku' sebagai tokoh utama menggunakan sudut pandang ...", options: ["orang ketiga", "orang kedua", "campuran", "orang pertama"], answer: 3, solution: "Langkah 1: sudut pandang menunjukkan posisi pengarang dalam cerita. Langkah 2: jika pengarang menjadi tokoh dan memakai kata ganti 'aku', disebut sudut pandang orang pertama. Langkah 3: jadi jawabannya orang pertama." },
    { q: "Penulisan kata depan berikut yang baku adalah ...", options: ["dari pada", "daripada", "dri pada", "dripada"], answer: 1, solution: "Langkah 1: kata ini sering salah ditulis terpisah. Langkah 2: menurut kaidah, 'daripada' sebagai kata depan ditulis serangkai (satu kata). Langkah 3: jadi bentuk bakunya adalah daripada." },
    { q: "Ungkapan 'besar kepala' memiliki makna ...", options: ["pintar", "berani", "pemarah", "sombong"], answer: 3, solution: "Langkah 1: ungkapan adalah gabungan kata yang maknanya tidak dapat ditebak dari kata-kata penyusunnya. Langkah 2: 'besar kepala' dipakai untuk orang yang merasa dirinya hebat dan meremehkan orang lain. Langkah 3: jadi maknanya adalah sombong." },
    { q: "Ciri utama karya ilmiah populer adalah ...", options: ["bahasa yang mudah dipahami masyarakat umum", "penuh istilah teknis tanpa penjelasan", "hanya boleh dibaca para ilmuwan", "tidak berdasarkan hasil penelitian"], answer: 0, solution: "Langkah 1: karya ilmiah populer menyajikan hasil ilmu pengetahuan untuk khalayak umum, bukan hanya kalangan akademik. Langkah 2: karena itu bahasanya harus lugas, sederhana, dan mudah dipahami. Langkah 3: jadi ciri utamanya adalah bahasa yang mudah dipahami masyarakat umum." },
    { q: "Tujuan penulisan karya ilmiah populer adalah ...", options: ["menyulitkan pembaca awam memahami ilmu pengetahuan", "menyebarluaskan hasil ilmu pengetahuan kepada masyarakat umum", "menyembunyikan temuan penelitian dari publik", "menambah jumlah istilah teknis dalam bahasa Indonesia"], answer: 1, solution: "Langkah 1: karya ilmiah populer ditulis agar ilmu pengetahuan tidak hanya dinikmati kalangan akademik. Langkah 2: sasaran pembacanya masyarakat umum, sehingga tujuannya menyebarluaskan ilmu pengetahuan kepada mereka. Langkah 3: jadi jawabannya menyebarluaskan hasil ilmu pengetahuan kepada masyarakat umum." },
    { q: "Urutan struktur karya ilmiah populer yang tepat adalah ...", options: ["penutup, isi, pendahuluan", "pendahuluan, isi/pembahasan, penutup", "abstrak, metode, hasil", "daftar isi, lampiran, sampul"], answer: 1, solution: "Langkah 1: karya ilmiah populer memiliki struktur sederhana seperti karangan umum. Langkah 2: dimulai dengan pendahuluan yang memaparkan latar belakang, dilanjutkan isi atau pembahasan, lalu ditutup dengan simpulan. Langkah 3: jadi urutan yang tepat adalah pendahuluan, isi/pembahasan, penutup." },
    { q: "Contoh karya ilmiah populer adalah ...", options: ["artikel sains di majalah umum", "tesis program doktor", "laporan penelitian laboratorium", "disertasi"], answer: 0, solution: "Langkah 1: karya ilmiah populer diterbitkan di media massa untuk pembaca umum. Langkah 2: tesis, disertasi, dan laporan lab adalah karya ilmiah formal untuk kalangan akademik. Langkah 3: jadi contohnya adalah artikel sains di majalah umum." },
    { q: "Perbedaan karya ilmiah populer dengan karya ilmiah formal terletak pada ...", options: ["jumlah halamannya", "warna sampulnya", "gaya bahasa dan tingkat keterbacaan untuk umum", "nama penulisnya"], answer: 2, solution: "Langkah 1: keduanya sama-sama berdasarkan fakta dan hasil penelitian. Langkah 2: yang membedakan adalah cara penyajiannya — karya ilmiah populer memakai bahasa yang mudah dicerna masyarakat umum, sedangkan karya ilmiah formal memakai bahasa baku yang ketat dan penuh istilah. Langkah 3: jadi perbedaannya terletak pada gaya bahasa dan tingkat keterbacaan untuk umum." },
    { q: "Perbedaan mendasar kritik sastra dan esai sastra adalah ...", options: ["kritik menilai karya secara objektif dengan tolok ukur tertentu, esai menyampaikan pandangan pribadi penulis secara subjektif", "kritik selalu lebih pendek daripada esai", "esai hanya membahas puisi, kritik hanya membahas novel", "kritik tidak boleh berisi penilaian, esai harus berisi penilaian"], answer: 0, solution: "Langkah 1: kritik sastra berfungsi menilai karya secara sistematis dan objektif dengan pendekatan atau teori tertentu. Langkah 2: esai sastra justru bersifat pribadi dan subjektif, menyampaikan pandangan penulis secara lincah. Langkah 3: jadi perbedaan mendasarnya adalah kritik menilai karya secara objektif dengan tolok ukur tertentu, sedangkan esai menyampaikan pandangan pribadi penulis secara subjektif." },
    { q: "Unsur yang harus ada dalam kritik sastra adalah ...", options: ["analisis kelebihan dan kekurangan karya", "daftar belanja penulis", "cerita kehidupan pribadi pembaca", "iklan penerbit"], answer: 0, solution: "Langkah 1: kritik sastra adalah timbangan atau penilaian terhadap sebuah karya. Langkah 2: untuk menilai, kritikus harus menguraikan apa saja kelebihan dan kekurangan karya tersebut dengan argumentasi. Langkah 3: jadi unsur yang harus ada adalah analisis kelebihan dan kekurangan karya." },
    { q: "Esai sastra bersifat ...", options: ["pribadi, subjektif, dan disajikan secara lincah", "kaku, resmi, dan penuh rumus", "hanya berisi data statistik", "ditulis tanpa sudut pandang penulis"], answer: 0, solution: "Langkah 1: esai berasal dari kata essai yang berarti percobaan atau upaya. Langkah 2: dalam esai, penulis bebas menuangkan pikiran dan perasaannya tentang suatu karya secara subjektif dengan bahasa yang lincah. Langkah 3: jadi esai sastra bersifat pribadi, subjektif, dan disajikan secara lincah." },
    { q: "Objek utama kritik sastra adalah ...", options: ["karya sastra itu sendiri", "kehidupan pribadi pengarang", "harga buku di pasaran", "jumlah pembaca"], answer: 0, solution: "Langkah 1: kritik sastra menilai sebuah karya. Langkah 2: yang dinilai adalah unsur-unsur di dalam karya itu sendiri, bukan pengarangnya, harganya, atau pembacanya. Langkah 3: jadi objek utamanya adalah karya sastra itu sendiri." },
    { q: "Tujuan kritik sastra adalah ...", options: ["memberi pertimbangan baik dan buruknya sebuah karya sastra", "menjatuhkan nama pengarang", "menaikkan harga buku", "memaksa pembaca membeli buku"], answer: 0, solution: "Langkah 1: kritik berasal dari kata kritis yang berarti menilai atau menimbang. Langkah 2: timbangan ini menghasilkan pertimbangan tentang mutu karya — apa yang baik dan apa yang kurang. Langkah 3: jadi tujuannya memberi pertimbangan baik dan buruknya sebuah karya sastra." },
    { q: "Novel yang ceritanya berlatar peristiwa sejarah masa lampau disebut novel ...", options: ["romantis", "sejarah", "detektif", "fantasi"], answer: 1, solution: "Langkah 1: novel dikelompokkan berdasarkan isi ceritanya. Langkah 2: novel yang mengangkat peristiwa atau tokoh sejarah sebagai latar ceritanya disebut novel sejarah. Langkah 3: jadi jawabannya novel sejarah." },
    { q: "Perbedaan novel dan cerpen terletak pada ...", options: ["novel lebih panjang dengan konflik yang lebih kompleks daripada cerpen", "novel tidak memiliki tokoh", "cerpen selalu lebih tebal dari novel", "novel tidak memiliki alur"], answer: 0, solution: "Langkah 1: novel adalah prosa fiksi yang panjang, sedangkan cerpen adalah prosa fiksi yang pendek. Langkah 2: karena panjang, novel mengembangkan konflik, tokoh, dan latar yang lebih kompleks, sedangkan cerpen hanya berfokus pada satu konflik utama. Langkah 3: jadi perbedaannya novel lebih panjang dengan konflik yang lebih kompleks daripada cerpen." },
    { q: "Kondisi sosial dan budaya masyarakat yang melatarbelakangi lahirnya sebuah novel termasuk unsur ...", options: ["intrinsik", "ekstrinsik", "kebahasaan", "tematik"], answer: 1, solution: "Langkah 1: unsur ekstrinsik adalah faktor dari luar karya yang memengaruhi isi karya. Langkah 2: kondisi sosial dan budaya masyarakat berada di luar teks novel tetapi ikut membentuk ceritanya. Langkah 3: jadi termasuk unsur ekstrinsik." },
    { q: "Novel yang mengisahkan petualangan memecahkan kasus kejahatan termasuk jenis novel ...", options: ["detektif", "romantis", "sejarah", "inspiratif"], answer: 0, solution: "Langkah 1: novel dikelompokkan berdasarkan isi dan tema ceritanya. Langkah 2: cerita tentang penyelidikan dan pemecahan kasus kejahatan termasuk ke dalam novel detektif. Langkah 3: jadi jawabannya novel detektif." },
    { q: "Perhatikan kutipan novel berikut: 'Rani menatap jendela kamarnya yang berembun. Hujan di luar seolah mengerti kesedihannya.' Unsur intrinsik yang menonjol pada kutipan tersebut adalah ...", options: ["latar suasana", "tema", "amanat", "sudut pandang"], answer: 0, solution: "Langkah 1: kutipan menggambarkan suasana hujan dan kesedihan tokoh. Langkah 2: penggambaran keadaan sekitar tokoh yang memengaruhi perasaan disebut latar suasana. Langkah 3: jadi unsur yang menonjol adalah latar suasana." },
    { q: "Hikayat umumnya mengandung nilai keteladanan, keberanian, dan kesetiaan. Nilai-nilai tersebut termasuk nilai ...", options: ["moral", "ekonomi", "politik", "estetika"], answer: 0, solution: "Langkah 1: keteladanan, keberanian, dan kesetiaan berkaitan dengan baik dan buruknya perilaku manusia. Langkah 2: nilai yang mengatur perilaku baik dan buruk disebut nilai moral. Langkah 3: jadi termasuk nilai moral." },
    { q: "Salah satu ciri hikayat adalah kemustahilan, contohnya ...", options: ["tokoh memiliki kesaktian yang tidak masuk akal", "tokoh membayar pajak tepat waktu", "tokoh naik angkutan umum ke pasar", "tokoh mengerjakan PR di rumah"], answer: 0, solution: "Langkah 1: kemustahilan berarti kejadian yang tidak mungkin terjadi di dunia nyata. Langkah 2: kesaktian tokoh seperti bisa terbang atau menghilang adalah hal yang mustahil. Langkah 3: jadi contohnya adalah tokoh memiliki kesaktian yang tidak masuk akal." },
    { q: "Hikayat disebut anonim karena ...", options: ["pengarangnya tidak diketahui", "tidak memiliki judul", "tidak memiliki tokoh", "tidak memiliki amanat"], answer: 0, solution: "Langkah 1: hikayat adalah sastra lisan yang diwariskan turun-temurun. Langkah 2: karena penyebarannya dari mulut ke mulut, nama pencipta aslinya tidak tercatat. Langkah 3: jadi hikayat disebut anonim karena pengarangnya tidak diketahui." },
    { q: "Perbedaan hikayat dengan cerpen modern adalah ...", options: ["hikayat bersifat anonim dan magis, cerpen modern pengarangnya jelas dan ceritanya realistis", "hikayat selalu lebih pendek dari cerpen", "cerpen modern tidak memiliki amanat", "hikayat ditulis dalam bahasa Inggris"], answer: 0, solution: "Langkah 1: hikayat adalah sastra lama yang pengarangnya tidak diketahui dan banyak memuat hal magis. Langkah 2: cerpen modern adalah sastra baru yang ditulis pengarang tertentu dengan cerita yang masuk akal. Langkah 3: jadi perbedaannya adalah hikayat bersifat anonim dan magis, sedangkan cerpen modern pengarangnya jelas dan ceritanya realistis." },
    { q: "Penggunaan kata-kata kuno seperti 'bermohon' dan 'titah' dalam hikayat menunjukkan bahwa hikayat ...", options: ["lahir pada masa lampau dengan latar budaya kerajaan", "ditulis dengan bahasa gaul masa kini", "diterjemahkan dari bahasa asing", "ditulis untuk anak-anak"], answer: 0, solution: "Langkah 1: kata bermohon dan titah adalah kata arkais yang berkaitan dengan kehidupan kerajaan. Langkah 2: kehadirannya menandakan hikayat berasal dari zaman dahulu dengan budaya istana. Langkah 3: jadi menunjukkan bahwa hikayat lahir pada masa lampau dengan latar budaya kerajaan." },
{ q: "Bagian awal teks anekdot yang berisi gambaran umum atau ringkasan isi cerita disebut ...", options: ["abstraksi", "orientasi", "krisis", "koda"], answer: 0, solution: "1. Struktur teks anekdot terdiri atas abstraksi, orientasi, krisis, reaksi, dan koda. 2. Abstraksi adalah bagian pembuka yang berisi gambaran umum atau ringkasan cerita. 3. Orientasi mengenalkan tokoh dan latar, sedangkan koda menjadi penutup. 4. Jadi, bagian yang dimaksud adalah abstraksi." },
{ q: "Pengenalan tokoh, latar tempat, dan latar waktu dalam teks anekdot terdapat pada bagian ...", options: ["koda", "orientasi", "reaksi", "abstraksi"], answer: 1, solution: "1. Setiap teks anekdot diawali pengenalan sebelum masuk ke inti cerita. 2. Pengenalan tokoh, tempat, dan waktu kejadian disebut orientasi. 3. Koda adalah penutup dan reaksi adalah tanggapan terhadap masalah. 4. Jadi, jawabannya adalah orientasi." },
{ q: "Bagian teks anekdot yang berisi cara tokoh menyelesaikan masalah atau menanggapi krisis disebut ...", options: ["orientasi", "abstraksi", "reaksi", "krisis"], answer: 2, solution: "1. Setelah krisis muncul, cerita membutuhkan penyelesaian. 2. Bagian yang berisi cara tokoh menyelesaikan atau menanggapi masalah disebut reaksi. 3. Krisis memuat puncak masalah, sedangkan abstraksi merangkum cerita. 4. Jadi, jawabannya adalah reaksi." },
{ q: "Bagian penutup teks anekdot yang berisi simpulan atau pesan disebut ...", options: ["reaksi", "krisis", "orientasi", "koda"], answer: 3, solution: "1. Teks anekdot diakhiri dengan bagian penutup. 2. Bagian penutup yang berisi simpulan atau pesan disebut koda. 3. Krisis adalah puncak masalah dan orientasi adalah pengenalan. 4. Jadi, jawabannya adalah koda." },
{ q: "Abstraksi dalam struktur teks anekdot bersifat ...", options: ["wajib dan harus panjang", "opsional, boleh ada boleh tidak", "harus berupa dialog", "selalu diletakkan di akhir"], answer: 1, solution: "1. Tidak semua bagian struktur anekdot wajib ada. 2. Abstraksi boleh dicantumkan boleh juga dihilangkan tanpa merusak cerita. 3. Bagian yang boleh ada boleh tidak disebut opsional. 4. Jadi, abstraksi bersifat opsional." },
{ q: "Anekdot yang menyindir kebijakan pemerintah atau ulah para pejabat termasuk jenis anekdot ...", options: ["pendidikan", "kesehatan", "politik", "olahraga"], answer: 2, solution: "1. Anekdot dikelompokkan berdasarkan topik yang disindir. 2. Sindiran terhadap kebijakan pemerintah atau ulah pejabat menyangkut urusan negara. 3. Urusan negara dan kekuasaan termasuk ranah politik. 4. Jadi, termasuk jenis anekdot politik." },
{ q: "Perhatikan topik anekdot berikut: \"Antrean panjang di kantor kelurahan karena petugas asyik bermain ponsel.\" Anekdot tersebut termasuk jenis anekdot ...", options: ["politik", "pendidikan", "keluarga", "pelayanan publik"], answer: 3, solution: "1. Perhatikan topiknya: antrean panjang di kantor kelurahan karena petugas bermain ponsel. 2. Kantor kelurahan adalah layanan yang diberikan pemerintah kepada masyarakat. 3. Anekdot yang menyindir layanan pemerintah disebut anekdot pelayanan publik. 4. Jadi, jawabannya adalah pelayanan publik." },
{ q: "Anekdot yang menyindir kebiasaan masyarakat membuang sampah sembarangan termasuk jenis anekdot ...", options: ["sosial", "politik", "pelayanan publik", "ekonomi"], answer: 0, solution: "1. Membuang sampah sembarangan adalah kebiasaan buruk sebagian masyarakat. 2. Anekdot yang menyindir perilaku masyarakat termasuk anekdot sosial. 3. Anekdot politik menyindir penguasa, sedangkan pelayanan publik menyindir layanan instansi. 4. Jadi, jawabannya adalah sosial." },
{ q: "Perhatikan kalimat: \"Ia merebut mikrofon lalu berlari ke atas panggung.\" Kata kerja aksi pada kalimat tersebut adalah ...", options: ["mikrofon", "merebut dan berlari", "panggung", "lalu"], answer: 1, solution: "1. Kata kerja aksi adalah kata kerja yang menunjukkan perbuatan fisik. 2. Pada kalimat tersebut, perbuatan yang dilakukan adalah merebut dan berlari. 3. Mikrofon dan panggung adalah kata benda, sedangkan lalu adalah konjungsi. 4. Jadi, kata kerja aksinya adalah merebut dan berlari." },
{ q: "Perhatikan kalimat: \"Petugas itu menghela napas, menutup loket, dan pergi begitu saja.\" Kelompok kata yang termasuk kata kerja aksi adalah ...", options: ["napas, loket", "petugas itu", "begitu saja", "menghela, menutup, pergi"], answer: 3, solution: "1. Kata kerja aksi menunjukkan perbuatan yang dilakukan subjek. 2. Perbuatan petugas pada kalimat itu adalah menghela, menutup, dan pergi. 3. Napas dan loket adalah kata benda, begitu saja adalah keterangan. 4. Jadi, kelompok kata kerja aksinya adalah menghela, menutup, pergi." },
{ q: "Perhatikan kalimat: \"Masa iya rakyat disuruh antre berjam-jam hanya untuk satu stempel?\" Kalimat tersebut termasuk kalimat retoris karena ...", options: ["diawali kata tanya siapa", "jawabannya sudah tertulis jelas", "tidak membutuhkan jawaban dan dipakai untuk menyindir", "diakhiri tanda seru"], answer: 2, solution: "1. Kalimat retoris adalah kalimat tanya yang tidak membutuhkan jawaban. 2. Kalimat tersebut dipakai untuk menyindir, bukan untuk benar-benar bertanya. 3. Ciri kalimat retoris adalah penutur tidak mengharapkan jawaban dari lawan bicara. 4. Jadi, kalimat tersebut termasuk kalimat retoris karena tidak membutuhkan jawaban dan dipakai untuk menyindir." },
{ q: "Manakah kalimat berikut yang termasuk kalimat retoris?", options: ["Siapa nama kepala desanya?", "Kapan jalan rusak ini akan diperbaiki?", "Berapa nomor antrean Anda?", "Di mana letak kantor kecamatan?"], answer: 1, solution: "1. Kalimat retoris adalah pertanyaan yang tidak memerlukan jawaban. 2. \"Kapan jalan rusak ini akan diperbaiki?\" adalah ungkapan kekesalan, bukan pertanyaan sungguhan. 3. Tiga pilihan lain adalah pertanyaan biasa yang membutuhkan jawaban. 4. Jadi, yang termasuk kalimat retoris adalah \"Kapan jalan rusak ini akan diperbaiki?\"." },
{ q: "Kata lalu, kemudian, dan setelah itu dalam teks anekdot termasuk konjungsi yang berfungsi ...", options: ["menunjukkan urutan peristiwa", "menyatakan pertentangan", "menyatakan sebab", "menyatakan syarat"], answer: 0, solution: "1. Kata lalu, kemudian, dan setelah itu menghubungkan peristiwa yang berurutan. 2. Konjungsi yang menyatakan urutan waktu disebut konjungsi temporal. 3. Konjungsi pertentangan menyatakan perlawanan, sedangkan sebab menyatakan alasan. 4. Jadi, fungsinya adalah menunjukkan urutan peristiwa." },
{ q: "Kalimat yang tepat untuk melengkapi rumpang berikut adalah: \"Antrean sudah mengular panjang, ... petugas justru asyik bermain ponsel.\"", options: ["dan", "atau", "akan tetapi", "karena"], answer: 2, solution: "1. Kalimat pertama dan kedua memiliki makna yang bertolak belakang. 2. Antrean panjang seharusnya dilayani cepat, tetapi petugas malah bermain ponsel. 3. Kata hubung yang menyatakan pertentangan adalah akan tetapi. 4. Jadi, kata yang tepat adalah akan tetapi." },
{ q: "Perhatikan kalimat anekdot: \"Tikus-tikus kantor itu akhirnya tertangkap KPK.\" Makna kiasan \"tikus kantor\" pada kalimat tersebut adalah ...", options: ["petugas kebersihan", "hewan pengerat di kantor", "satpam kantor", "para koruptor"], answer: 3, solution: "1. \"Tikus kantor\" bukan hewan sungguhan, melainkan makna kiasan. 2. Istilah ini dipakai untuk orang yang menggerogoti uang negara dari dalam kantor. 3. Orang yang korupsi disebut koruptor. 4. Jadi, makna kiasannya adalah para koruptor." },
{ q: "Dalam teks anekdot, ungkapan \"kursi empuk\" bermakna ...", options: ["kursi yang empuk untuk diduduki", "jabatan yang nyaman dan menguntungkan", "kursi kantor yang baru dibeli", "tempat duduk para pejabat"], answer: 1, solution: "1. \"Kursi empuk\" dalam anekdot bukan kursi yang sebenarnya. 2. Ungkapan ini melambangkan kedudukan yang nyaman dan banyak keuntungannya. 3. Kedudukan atau jabatan yang nyaman dan menguntungkan itulah maknanya. 4. Jadi, bermakna jabatan yang nyaman dan menguntungkan." },
{ q: "Salah satu kaidah kebahasaan teks anekdot adalah banyak menggunakan ...", options: ["istilah ilmiah yang rumit", "data statistik dan grafik", "kalimat langsung berupa dialog tokoh", "rumus matematika"], answer: 2, solution: "1. Teks anekdot menceritakan kejadian lucu yang melibatkan tokoh. 2. Agar hidup, percakapan tokoh sering ditampilkan langsung dengan tanda petik. 3. Kalimat langsung berupa dialog tokoh memang menjadi ciri kebahasaan anekdot. 4. Jadi, jawabannya adalah kalimat langsung berupa dialog tokoh." },
{ q: "Perhatikan anekdot berikut: \"Seorang pejabat berjanji jalan desa akan diperbaiki sebelum musim panen. Setahun berlalu, jalan tetap berlubang, tetapi spanduk janjinya masih terpampang megah di gapura desa.\" Pesan atau sindiran yang disampaikan anekdot tersebut adalah ...", options: ["menyindir pejabat yang ingkar janji", "memuji keindahan spanduk desa", "mengajak warga memperbaiki jalan", "mengkritik musim panen yang gagal"], answer: 0, solution: "1. Pejabat berjanji memperbaiki jalan sebelum panen, tetapi setahun berlalu jalan tetap berlubang. 2. Spanduk janjinya justru masih terpampang megah. 3. Kontras ini menyindir pejabat yang tidak menepati janjinya. 4. Jadi, pesannya adalah menyindir pejabat yang ingkar janji." },
{ q: "Perhatikan anekdot berikut: \"Pak RT mengumumkan iuran Rp50 ribu untuk perbaikan gapura. Warga membayar tepat waktu. Tiga bulan berlalu, gapura tak kunjung diperbaiki, tetapi sebuah mobil baru terparkir di halaman rumah Pak RT.\" Bagian krisis ditunjukkan oleh kalimat ...", options: ["Pak RT mengumumkan iuran Rp50 ribu untuk perbaikan gapura.", "Tiga bulan berlalu, gapura tak kunjung diperbaiki, tetapi sebuah mobil baru terparkir di halaman rumah Pak RT.", "Warga membayar tepat waktu.", "Warga RT 05 mengadakan rapat rutin."], answer: 1, solution: "1. Krisis adalah bagian yang memuat puncak masalah atau kekonyolan. 2. Kalimat pertama dan ketiga baru pengantar, sedangkan kalimat kedua memuat ironi: gapura tak diperbaiki tetapi mobil baru muncul. 3. Ironi dana iuran yang diduga diselewengkan adalah puncak masalahnya. 4. Jadi, bagian krisis ditunjukkan kalimat kedua." },
{ q: "Lanjutan anekdot: \"Warga pun memasang spanduk di gapura bertuliskan: 'Gapura kami sudah pindah ke garasi Pak RT.'\" Kutipan tersebut termasuk bagian ... karena ...", options: ["orientasi, mengenalkan tokoh", "krisis, memuat puncak masalah", "abstraksi, merangkum cerita", "reaksi, berisi cara tokoh menanggapi masalah"], answer: 3, solution: "1. Setelah krisis, warga menanggapi dengan memasang spanduk sindiran. 2. Bagian yang berisi tanggapan atau cara menyelesaikan masalah disebut reaksi. 3. Orientasi mengenalkan tokoh dan krisis memuat puncak masalah. 4. Jadi, kutipan tersebut termasuk reaksi karena berisi cara tokoh menanggapi masalah." },
{ q: "Penutup anekdot: \"Amanah itu berat; jangan sampai iuran warga berubah menjadi cicilan mobil.\" Bagian tersebut termasuk ... karena berisi ...", options: ["krisis, puncak kekonyolan", "orientasi, latar cerita", "koda, simpulan dan pesan moral", "reaksi, tanggapan tokoh"], answer: 2, solution: "1. Kalimat terakhir menyampaikan simpulan dan nasihat tentang amanah. 2. Bagian penutup anekdot yang berisi simpulan atau pesan moral disebut koda. 3. Krisis memuat puncak masalah dan reaksi memuat tanggapan. 4. Jadi, termasuk koda karena berisi simpulan dan pesan moral." },
{ q: "Perbedaan anekdot dengan cerita lucu biasa adalah ...", options: ["anekdot mengandung kritik atau sindiran terhadap suatu keadaan", "anekdot hanya menghibur tanpa pesan", "cerita lucu selalu lebih panjang", "anekdot tidak memiliki struktur"], answer: 0, solution: "1. Cerita lucu biasa bertujuan menghibur saja. 2. Anekdot memang lucu, tetapi kelucuan itu membungkus kritik terhadap suatu keadaan. 3. Adanya kritik atau sindiran inilah pembeda utamanya. 4. Jadi, perbedaannya adalah anekdot mengandung kritik atau sindiran terhadap suatu keadaan." },
{ q: "Kritik dalam teks anekdot disampaikan secara ...", options: ["terang-terangan dan kasar", "berupa data dan grafik", "melalui peraturan tertulis", "tersirat dan dibalut humor"], answer: 3, solution: "1. Anekdot tidak mengkritik secara terang-terangan. 2. Kritik disampaikan secara tersirat melalui cerita yang lucu. 3. Humor menjadi bungkus agar sindiran terasa ringan. 4. Jadi, kritik disampaikan secara tersirat dan dibalut humor." },
{ q: "Selain menghibur pembaca, teks anekdot bertujuan ...", options: ["menambah pengetahuan ilmiah", "menyadarkan pembaca akan suatu penyimpangan", "memberi petunjuk melakukan sesuatu", "mempromosikan suatu produk"], answer: 1, solution: "1. Anekdot memang menghibur pembaca dengan kelucuannya. 2. Di balik itu, anekdot menyoroti penyimpangan agar pembaca sadar. 3. Fungsi sosialnya adalah menyadarkan pembaca. 4. Jadi, tujuannya adalah menyadarkan pembaca akan suatu penyimpangan." },
{ q: "Teks anekdot umumnya diangkat dari ...", options: ["khayalan pengarang semata", "mitos dan legenda kuno", "peristiwa nyata dalam kehidupan sehari-hari", "penelitian ilmiah"], answer: 2, solution: "1. Anekdot terasa dekat karena mengangkat kejadian sehari-hari. 2. Bahan ceritanya umumnya peristiwa nyata yang benar-benar terjadi. 3. Mitos dan penelitian ilmiah bukan sumber anekdot. 4. Jadi, anekdot umumnya diangkat dari peristiwa nyata dalam kehidupan sehari-hari." },
{ q: "Perhatikan kutipan hikayat berikut: \"Maka terbanglah Sang Ksatria ke kayangan dalam sekejap mata, menembus awan tanpa sayap.\" Unsur kemustahilan pada kutipan tersebut ditunjukkan oleh ...", options: ["tokoh yang bernama Sang Ksatria", "adanya kata sekejap mata", "tokoh yang dapat terbang ke kayangan", "latar waktu pada siang hari"], answer: 2, solution: "1. Kemustahilan adalah kejadian yang tidak mungkin terjadi di dunia nyata. 2. Manusia tidak dapat terbang ke kayangan tanpa sayap. 3. Itulah unsur yang tidak masuk akal pada kutipan. 4. Jadi, unsur kemustahilan ditunjukkan oleh tokoh yang dapat terbang ke kayangan." },
{ q: "Kesaktian yang dimiliki tokoh dalam hikayat berfungsi untuk ...", options: ["menunjukkan kehebatan dan kelebihan tokoh dibanding manusia biasa", "membuat cerita menjadi membosankan", "menghilangkan nilai moral cerita", "mengganti peran tokoh utama"], answer: 0, solution: "1. Tokoh hikayat sering digambarkan memiliki kesaktian luar biasa. 2. Kesaktian itu membedakannya dari manusia biasa. 3. Tujuannya menonjolkan kehebatan dan kelebihan tokoh utama. 4. Jadi, kesaktian berfungsi menunjukkan kehebatan dan kelebihan tokoh dibanding manusia biasa." },
{ q: "Hikayat bersifat anonim karena pada awalnya hikayat disebarkan secara ...", options: ["tertulis melalui media cetak", "lisan dari mulut ke mulut secara turun-temurun", "siaran televisi", "media sosial"], answer: 1, solution: "1. Hikayat adalah sastra lisan masyarakat Melayu lama. 2. Ceritanya diwariskan dari mulut ke mulut secara turun-temurun. 3. Karena itu nama pencipta aslinya tidak tercatat. 4. Jadi, hikayat bersifat anonim karena disebarkan secara lisan turun-temurun." },
{ q: "Ciri khas bahasa arkais dalam hikayat adalah ...", options: ["menggunakan bahasa gaul masa kini", "memakai istilah teknologi modern", "ditulis dengan kalimat yang sangat pendek", "banyak menggunakan kata kuno yang sudah tidak lazim dipakai"], answer: 3, solution: "1. Bahasa arkais adalah bahasa kuno yang sudah jarang dipakai. 2. Ciri khasnya adalah banyak kata kuno yang tidak lazim dalam bahasa kini. 3. Bahasa gaul dan istilah teknologi justru ciri bahasa modern. 4. Jadi, ciri khasnya adalah banyak menggunakan kata kuno yang sudah tidak lazim dipakai." },
{ q: "Berikut ini latar yang menunjukkan sifat istanasentris pada hikayat adalah ...", options: ["istana raja yang megah", "pasar tradisional yang ramai", "sawah milik petani", "pelabuhan tempat berlabuh"], answer: 0, solution: "1. Istanasentris berarti cerita berpusat pada kehidupan istana. 2. Latar yang berkaitan dengan istana adalah istana raja yang megah. 3. Pasar, sawah, dan pelabuhan adalah latar kehidupan rakyat biasa. 4. Jadi, latar yang menunjukkan istanasentris adalah istana raja yang megah." },
{ q: "Hikayat dikatakan bersifat didaktis karena ...", options: ["hanya menceritakan perang", "tidak memiliki amanat", "mengandung ajaran atau pelajaran moral bagi pembaca", "ditulis tanpa tujuan"], answer: 2, solution: "1. Didaktis berasal dari kata didaktik yang berarti bersifat mendidik. 2. Hikayat selalu menyelipkan ajaran dan pelajaran moral. 3. Inilah yang membuat hikayat bersifat didaktis. 4. Jadi, hikayat didaktis karena mengandung ajaran atau pelajaran moral bagi pembaca." },
{ q: "Judul hikayat umumnya menggunakan ...", options: ["nama pengarangnya", "nama tokoh utama cerita", "nama tempat penerbitan", "tanggal penulisan"], answer: 1, solution: "1. Perhatikan judul hikayat yang terkenal: Hikayat Hang Tuah, Hikayat Si Miskin. 2. Judul-judul itu memakai nama tokoh utamanya. 3. Inilah kebiasaan penamaan hikayat Melayu klasik. 4. Jadi, judul hikayat umumnya menggunakan nama tokoh utama cerita." },
{ q: "Penggunaan kata ganti \"hamba\" dan \"tuan\" dalam hikayat mencerminkan ...", options: ["budaya feodal dan tata krama istana pada masa lampau", "bahasa pergaulan anak muda", "istilah perdagangan modern", "bahasa resmi pemerintahan kini"], answer: 0, solution: "1. Kata hamba dipakai rakyat atau bawahan, sedangkan tuan dipakai untuk atasan. 2. Pemakaian ini mencerminkan hubungan bertingkat antara rakyat dan penguasa. 3. Budaya yang menempatkan rakyat di bawah penguasa disebut budaya feodal. 4. Jadi, mencerminkan budaya feodal dan tata krama istana pada masa lampau." },
{ q: "Hikayat dapat memuat peristiwa yang tidak masuk akal karena hikayat ...", options: ["ditulis berdasarkan penelitian ilmiah", "merupakan laporan kejadian nyata", "disadur dari berita koran", "lahir dari khayalan dan imajinasi masyarakat masa lampau"], answer: 3, solution: "1. Peristiwa mustahil seperti terbang ke kayangan tidak terjadi di dunia nyata. 2. Hikayat lahir dari khayalan dan imajinasi masyarakat masa lampau. 3. Khayalan inilah yang memungkinkan peristiwa tidak logis. 4. Jadi, hikayat dapat memuat peristiwa tidak masuk akal karena lahir dari khayalan masyarakat masa lampau." },
{ q: "Hikayat digolongkan sebagai prosa lama karena ...", options: ["ditulis dengan bahasa Inggris", "baru muncul abad ke-21", "lahir dan berkembang pada masa sastra Melayu klasik", "berbentuk bait dan baris"], answer: 2, solution: "1. Prosa lama adalah karya prosa yang lahir pada zaman sastra Melayu klasik. 2. Hikayat berkembang pada masa tersebut. 3. Hikayat berbentuk prosa, bukan bait dan baris seperti puisi. 4. Jadi, hikayat digolongkan prosa lama karena lahir pada masa sastra Melayu klasik." },
{ q: "Alih bahasa hikayat adalah kegiatan ...", options: ["mengubah bahasa arkais hikayat menjadi bahasa Indonesia modern tanpa mengubah isi cerita", "menerjemahkan hikayat ke bahasa asing", "meringkas hikayat menjadi satu paragraf", "mengubah hikayat menjadi puisi"], answer: 0, solution: "1. Bahasa hikayat adalah bahasa arkais yang sulit dipahami. 2. Alih bahasa berarti memindahkan bahasa arkais ke bahasa Indonesia modern. 3. Isi dan amanat cerita tidak boleh diubah. 4. Jadi, alih bahasa adalah mengubah bahasa arkais menjadi bahasa modern tanpa mengubah isi cerita." },
{ q: "Tujuan melakukan alih bahasa terhadap hikayat adalah ...", options: ["agar hikayat menjadi lebih panjang", "agar mudah dipahami oleh pembaca masa kini", "agar pengarangnya dikenal", "agar hikayat kehilangan nilai lamanya"], answer: 1, solution: "1. Pembaca masa kini kesulitan memahami bahasa arkais. 2. Setelah dialihbahasakan, hikayat menjadi mudah dibaca. 3. Inilah tujuan utama kegiatan alih bahasa. 4. Jadi, tujuannya agar mudah dipahami oleh pembaca masa kini." },
{ q: "Dalam mengalihbahasakan hikayat, hal yang harus dipertahankan adalah ...", options: ["kata-kata arkaisnya", "kesalahan bahasanya", "jumlah halamannya", "isi dan amanat cerita aslinya"], answer: 3, solution: "1. Alih bahasa hanya mengganti bahasa, bukan mengganti cerita. 2. Isi dan amanat asli adalah jiwa hikayat. 3. Keduanya harus dipertahankan apa adanya. 4. Jadi, yang harus dipertahankan adalah isi dan amanat cerita aslinya." },
{ q: "Perhatikan kutipan hikayat berikut: \"Maka mengaku dosalah ia di hadapan baginda, tiada disembunyikannya kesalahannya sedikit jua.\" Nilai yang terkandung dalam kutipan tersebut adalah nilai ...", options: ["ekonomi", "politik", "moral", "estetika"], answer: 2, solution: "1. Kutipan menunjukkan tokoh berani mengakui kesalahannya. 2. Kejujuran berkaitan dengan baik dan buruknya perilaku manusia. 3. Nilai yang mengatur perilaku baik dan buruk disebut nilai moral. 4. Jadi, nilai yang terkandung adalah nilai moral." },
{ q: "Tokoh hikayat yang menepati janjinya kepada rakyat meski harus menempuh bahaya menunjukkan nilai ...", options: ["moral", "ekonomi", "politik", "hukum"], answer: 0, solution: "1. Menepati janji adalah perilaku terpuji. 2. Perilaku baik dan buruk diatur oleh nilai moral. 3. Nilai ekonomi berkaitan dengan usaha dan harta, bukan janji. 4. Jadi, menunjukkan nilai moral." },
{ q: "Perhatikan kutipan hikayat berikut: \"Maka berdoalah ia ke hadirat Tuhan, memohon keselamatan bagi negerinya.\" Nilai yang dominan pada kutipan tersebut adalah nilai ...", options: ["ekonomi", "agama", "sosial", "budaya"], answer: 1, solution: "1. Kutipan menunjukkan tokoh berdoa kepada Tuhan. 2. Doa adalah wujud hubungan manusia dengan Tuhan. 3. Nilai yang berkaitan dengan keyakinan dan ibadah disebut nilai agama. 4. Jadi, nilai yang dominan adalah nilai agama." },
{ q: "Tokoh hikayat yang selalu bersyukur atas nikmat Tuhan dan rajin beribadah mencerminkan nilai ...", options: ["sosial", "ekonomi", "politik", "agama"], answer: 3, solution: "1. Bersyukur dan rajin beribadah adalah wujud ketaatan kepada Tuhan. 2. Ketaatan beragama termasuk dalam nilai agama. 3. Nilai sosial berkaitan dengan hubungan antarmanusia. 4. Jadi, mencerminkan nilai agama." },
{ q: "Penggambaran upacara adat panen yang meriah dalam hikayat mengandung nilai ...", options: ["budaya", "ekonomi", "politik", "hukum"], answer: 0, solution: "1. Upacara adat panen adalah tradisi turun-temurun masyarakat. 2. Tradisi dan adat istiadat termasuk unsur kebudayaan. 3. Nilai yang berkaitan dengan adat dan tradisi disebut nilai budaya. 4. Jadi, mengandung nilai budaya." },
{ q: "Perhatikan kutipan hikayat berikut: \"Maka dipersembahkanlah tarian oleh para dayang untuk menyambut tamu agung.\" Kutipan tersebut mencerminkan nilai ...", options: ["ekonomi", "politik", "budaya", "moral"], answer: 2, solution: "1. Tarian persembahan adalah kesenian tradisional. 2. Kesenian merupakan bagian dari kebudayaan. 3. Nilai yang berkaitan dengan kebudayaan disebut nilai budaya. 4. Jadi, kutipan tersebut mencerminkan nilai budaya." },
{ q: "Tokoh hikayat yang membagikan lumbung padinya kepada rakyat yang kelaparan menunjukkan nilai ...", options: ["ekonomi", "sosial", "politik", "estetika"], answer: 1, solution: "1. Tokoh membagikan padinya kepada rakyat yang kelaparan. 2. Perbuatan menolong sesama berkaitan dengan hubungan antarmanusia. 3. Nilai tentang hubungan dan kepedulian sosial disebut nilai sosial. 4. Jadi, menunjukkan nilai sosial." },
{ q: "Sikap gotong royong warga membangun balai desa yang digambarkan dalam hikayat termasuk nilai ...", options: ["ekonomi", "politik", "hukum", "sosial"], answer: 3, solution: "1. Gotong royong adalah kerja sama warga untuk kepentingan bersama. 2. Kerja sama antarwarga menyangkut kehidupan bermasyarakat. 3. Nilai yang berkaitan dengan kehidupan bermasyarakat disebut nilai sosial. 4. Jadi, termasuk nilai sosial." },
{ q: "Tokoh hikayat yang bekerja keras mencari nafkah dan hidup hemat mencerminkan nilai ...", options: ["ekonomi", "moral", "agama", "budaya"], answer: 0, solution: "1. Bekerja keras mencari nafkah berkaitan dengan usaha ekonomi. 2. Hidup hemat berkaitan dengan pengelolaan harta. 3. Nilai yang berkaitan dengan usaha dan harta disebut nilai ekonomi. 4. Jadi, mencerminkan nilai ekonomi." },
{ q: "Amanat agar rajin menuntut ilmu yang terdapat dalam hikayat termasuk nilai ...", options: ["ekonomi", "politik", "pendidikan", "sosial"], answer: 2, solution: "1. Amanat agar rajin menuntut ilmu berkaitan dengan belajar. 2. Belajar dan ilmu pengetahuan termasuk bidang pendidikan. 3. Nilai yang berkaitan dengan pendidikan disebut nilai pendidikan. 4. Jadi, termasuk nilai pendidikan." },
{ q: "Tokoh hikayat yang rela merantau jauh untuk berguru kepada orang pandai menunjukkan nilai ...", options: ["ekonomi", "pendidikan", "politik", "hukum"], answer: 1, solution: "1. Tokoh rela merantau jauh demi berguru kepada orang pandai. 2. Berguru adalah usaha menuntut ilmu. 3. Usaha menuntut ilmu mencerminkan nilai pendidikan. 4. Jadi, menunjukkan nilai pendidikan." },
{ q: "Raja dalam hikayat yang tetap rendah hati dan mau mendengar keluhan rakyatnya menunjukkan nilai ...", options: ["politik", "ekonomi", "hukum", "moral"], answer: 3, solution: "1. Raja yang rendah hati dan mau mendengar keluhan rakyat menunjukkan akhlak baik. 2. Akhlak berkaitan dengan baik dan buruknya perilaku. 3. Nilai tentang perilaku baik dan buruk disebut nilai moral. 4. Jadi, menunjukkan nilai moral." },
{ q: "Ciri utama teks biografi adalah ...", options: ["menceritakan khayalan penulis semata", "menceritakan riwayat hidup seorang tokoh yang ditulis oleh orang lain", "berisi kumpulan puisi penyair", "berupa dialog drama"], answer: 1, solution: "1. Biografi menceritakan perjalanan hidup seorang tokoh. 2. Penulisnya adalah orang lain, bukan tokoh itu sendiri. 3. Inilah ciri utama yang membedakannya dari autobiografi. 4. Jadi, ciri utamanya adalah menceritakan riwayat hidup tokoh yang ditulis oleh orang lain." },
{ q: "Biografi bersifat faktual, artinya ...", options: ["berdasarkan khayalan penulis", "berisi ramalan masa depan", "berupa cerita fiksi", "berdasarkan fakta dan kejadian nyata dalam kehidupan tokoh"], answer: 3, solution: "1. Faktual berarti berdasarkan fakta. 2. Isi biografi harus sesuai kejadian nyata dalam hidup tokoh. 3. Khayalan dan ramalan bukan fakta. 4. Jadi, bersifat faktual artinya berdasarkan fakta dan kejadian nyata dalam kehidupan tokoh." },
{ q: "Bagian orientasi pada teks biografi berisi ...", options: ["pengenalan tokoh, seperti identitas dan latar belakangnya", "komentar penulis tentang tokoh", "daftar pustaka", "ucapan terima kasih"], answer: 0, solution: "1. Orientasi adalah bagian pembuka teks biografi. 2. Fungsinya mengenalkan tokoh kepada pembaca. 3. Yang dikenalkan meliputi identitas dan latar belakang tokoh. 4. Jadi, orientasi berisi pengenalan tokoh seperti identitas dan latar belakangnya." },
{ q: "Bagian yang memuat rangkaian peristiwa penting dalam kehidupan tokoh disebut ...", options: ["orientasi", "koda", "peristiwa penting", "abstraksi"], answer: 2, solution: "1. Setelah orientasi, biografi memaparkan perjalanan hidup tokoh. 2. Rangkaian kejadian penting itu disebut peristiwa penting. 3. Koda dan abstraksi adalah struktur anekdot, bukan biografi. 4. Jadi, jawabannya adalah peristiwa penting." },
{ q: "Bagian masalah dalam teks biografi memuat ...", options: ["identitas dan nama tokoh", "hambatan, tantangan, atau konflik yang dihadapi tokoh", "kesimpulan penulis", "daftar prestasi tanpa hambatan"], answer: 1, solution: "1. Perjalanan hidup tokoh tidak selalu mulus. 2. Hambatan, tantangan, atau konflik yang dihadapi dimuat pada bagian masalah. 3. Identitas tokoh ada di orientasi dan kesimpulan ada di reorientasi. 4. Jadi, bagian masalah memuat hambatan, tantangan, atau konflik yang dihadapi tokoh." },
{ q: "Bagian reorientasi dalam teks biografi terletak pada ...", options: ["akhir teks sebagai penutup", "awal teks", "tengah teks", "setiap paragraf"], answer: 0, solution: "1. Reorientasi berisi simpulan dan kesan penulis tentang tokoh. 2. Simpulan selalu ditempatkan di akhir tulisan. 3. Awal teks ditempati orientasi. 4. Jadi, reorientasi terletak pada akhir teks sebagai penutup." },
{ q: "Kata ganti yang dominan digunakan dalam teks biografi adalah kata ganti orang ...", options: ["pertama", "kedua", "jamak saja", "ketiga"], answer: 3, solution: "1. Biografi ditulis oleh orang lain tentang tokoh. 2. Penulis menyebut tokoh dengan ia, dia, beliau, atau -nya. 3. Kata ganti itu termasuk kata ganti orang ketiga. 4. Jadi, kata ganti yang dominan adalah kata ganti orang ketiga." },
{ q: "Perhatikan kalimat: \"Beliau mendedikasikan hidupnya untuk pendidikan anak bangsa.\" Kata \"beliau\" menunjukkan bahwa biografi ditulis dengan sudut pandang orang ...", options: ["pertama", "kedua", "ketiga", "campuran"], answer: 2, solution: "1. Kata beliau merujuk pada orang yang dibicarakan. 2. Orang yang dibicarakan adalah orang ketiga. 3. Sudut pandang orang pertama memakai aku atau saya. 4. Jadi, ditulis dengan sudut pandang orang ketiga." },
{ q: "Kata kerja material adalah kata kerja yang menunjukkan ...", options: ["aktivitas fisik yang dapat dilihat", "proses berpikir", "perasaan batin", "keadaan benda"], answer: 0, solution: "1. Kata kerja material berkaitan dengan kata materi yang berwujud. 2. Kata kerja ini menunjukkan aktivitas fisik yang dapat dilihat. 3. Proses berpikir termasuk kata kerja mental. 4. Jadi, kata kerja material menunjukkan aktivitas fisik yang dapat dilihat." },
{ q: "Manakah kata berikut yang termasuk kata kerja material?", options: ["berpikir", "membangun", "merasa", "berharap"], answer: 1, solution: "1. Membangun adalah perbuatan fisik yang hasilnya terlihat. 2. Berpikir, merasa, dan berharap adalah proses batin. 3. Kata kerja perbuatan fisik disebut kata kerja material. 4. Jadi, yang termasuk kata kerja material adalah membangun." },
{ q: "Kata kerja mental menunjukkan ...", options: ["aktivitas fisik", "gerakan tubuh", "perubahan wujud", "proses berpikir atau merasa"], answer: 3, solution: "1. Kata kerja mental berkaitan dengan kerja pikiran dan batin. 2. Kata kerja ini menunjukkan proses berpikir atau merasa. 3. Aktivitas fisik termasuk kata kerja material. 4. Jadi, kata kerja mental menunjukkan proses berpikir atau merasa." },
{ q: "Manakah kata berikut yang termasuk kata kerja mental?", options: ["menulis", "berlari", "mengagumi", "membangun"], answer: 2, solution: "1. Mengagumi adalah perasaan kagum dalam batin. 2. Menulis, berlari, dan membangun adalah perbuatan fisik. 3. Kata kerja yang menunjukkan rasa atau pikiran disebut kata kerja mental. 4. Jadi, yang termasuk kata kerja mental adalah mengagumi." },
{ q: "Sebuah buku menceritakan riwayat hidup B.J. Habibie dan ditulis oleh penulis lain. Buku tersebut termasuk ...", options: ["biografi", "autobiografi", "anekdot", "hikayat"], answer: 0, solution: "1. Buku itu menceritakan riwayat hidup B.J. Habibie. 2. Penulisnya adalah orang lain, bukan Habibie sendiri. 3. Riwayat hidup yang ditulis orang lain disebut biografi. 4. Jadi, buku tersebut termasuk biografi." },
{ q: "Autobiografi umumnya menggunakan sudut pandang orang pertama yang ditandai dengan kata ganti ...", options: ["dia atau beliau", "aku atau saya", "mereka", "kamu"], answer: 1, solution: "1. Autobiografi ditulis oleh tokoh itu sendiri. 2. Penulis menyebut dirinya dengan aku atau saya. 3. Aku dan saya adalah kata ganti orang pertama. 4. Jadi, autobiografi memakai kata ganti aku atau saya." },
{ q: "Tujuan utama penulisan teks biografi tokoh adalah ...", options: ["menghibur dengan cerita lucu", "menakut-nakuti pembaca", "mempromosikan produk", "memberikan keteladanan dan inspirasi kepada pembaca"], answer: 3, solution: "1. Biografi mengisahkan tokoh yang berprestasi dan berjasa. 2. Kisah itu ditulis agar pembaca meneladani sikap tokoh. 3. Memberi teladan dan inspirasi adalah tujuan utamanya. 4. Jadi, tujuannya adalah memberikan keteladanan dan inspirasi kepada pembaca." },
{ q: "Perhatikan kutipan biografi berikut: \"Meski gagal berkali-kali, ia tak pernah berhenti mencoba hingga akhirnya berhasil.\" Keteladanan yang dapat diambil dari kutipan tersebut adalah ...", options: ["mudah putus asa", "suka menunda pekerjaan", "pantang menyerah dan tekun berusaha", "mengandalkan orang lain"], answer: 2, solution: "1. Tokoh gagal berkali-kali tetapi terus mencoba. 2. Sikap tidak mudah menyerah disebut pantang menyerah. 3. Terus berusaha dengan tekun adalah keteladanan darinya. 4. Jadi, keteladanannya adalah pantang menyerah dan tekun berusaha." },
{ q: "Teks biografi banyak menggunakan kata kerja bentuk lampau karena ...", options: ["menceritakan peristiwa yang sudah terjadi", "meramalkan masa depan tokoh", "berisi perintah kepada pembaca", "mengajak pembaca berdialog"], answer: 0, solution: "1. Biografi menceritakan perjalanan hidup tokoh. 2. Peristiwa itu sudah terjadi pada masa lampau. 3. Karena itu dipakai kata kerja bentuk lampau. 4. Jadi, banyak memakai kata kerja lampau karena menceritakan peristiwa yang sudah terjadi." },
{ q: "Konjungsi seperti kemudian, setelah itu, dan pada tahun ... dalam teks biografi berfungsi ...", options: ["menyatakan pertentangan", "menata urutan peristiwa secara kronologis", "menyatakan syarat", "menunjukkan akibat"], answer: 1, solution: "1. Peristiwa dalam biografi disusun dari masa kecil hingga akhir hayat. 2. Konjungsi kemudian dan setelah itu menandai urutan waktu. 3. Susunan peristiwa berdasarkan waktu disebut kronologis. 4. Jadi, fungsinya menata urutan peristiwa secara kronologis." },
{ q: "Urutan struktur teks biografi yang tepat adalah ...", options: ["reorientasi - orientasi - peristiwa - masalah", "masalah - reorientasi - orientasi - peristiwa", "peristiwa - masalah - orientasi - reorientasi", "orientasi - peristiwa penting - masalah - reorientasi"], answer: 3, solution: "1. Teks biografi dibuka dengan pengenalan tokoh yaitu orientasi. 2. Dilanjutkan rangkaian peristiwa penting dan masalah yang dihadapi. 3. Diakhiri simpulan penulis yaitu reorientasi. 4. Jadi, urutan yang tepat adalah orientasi - peristiwa penting - masalah - reorientasi." },
{ q: "Perhatikan kutipan biografi berikut: \"R.A. Kartini lahir di Jepara pada 21 April 1879.\" Kutipan tersebut termasuk bagian ...", options: ["masalah", "reorientasi", "orientasi", "peristiwa penting"], answer: 2, solution: "1. Kutipan menyebutkan nama, tempat, dan tanggal lahir tokoh. 2. Informasi identitas tokoh adalah pengenalan. 3. Bagian pengenalan dalam biografi disebut orientasi. 4. Jadi, kutipan tersebut termasuk bagian orientasi." },
{ q: "Perhatikan kutipan biografi berikut: \"Ia harus berjuang melawan adat yang melarang perempuan bersekolah.\" Kutipan tersebut termasuk bagian ...", options: ["masalah", "orientasi", "reorientasi", "abstraksi"], answer: 0, solution: "1. Kutipan menunjukkan tokoh menghadapi larangan adat. 2. Larangan itu adalah hambatan dalam perjuangannya. 3. Hambatan atau konflik tokoh dimuat pada bagian masalah. 4. Jadi, kutipan tersebut termasuk bagian masalah." },
{ q: "Perhatikan kutipan biografi berikut: \"Pada tahun 1903, ia mendirikan sekolah untuk anak-anak perempuan.\" Kutipan tersebut termasuk bagian ...", options: ["orientasi", "peristiwa penting", "masalah", "reorientasi"], answer: 1, solution: "1. Kutipan menyebutkan pendirian sekolah pada tahun 1903. 2. Itu adalah kejadian penting dalam hidup tokoh. 3. Rangkaian kejadian penting dimuat pada bagian peristiwa penting. 4. Jadi, kutipan tersebut termasuk bagian peristiwa penting." },
{ q: "Agar dapat dipertanggungjawabkan kebenarannya, isi teks biografi harus ...", options: ["ditambah khayalan penulis", "disembunyikan sumbernya", "ditulis tanpa riset", "didukung data dan fakta yang benar"], answer: 3, solution: "1. Biografi bersifat faktual sehingga isinya harus benar. 2. Kebenaran itu harus dapat dibuktikan. 3. Pembuktian dilakukan dengan data dan fakta yang benar. 4. Jadi, isi biografi harus didukung data dan fakta yang benar." },
{ q: "Tokoh yang ditulis dalam teks biografi umumnya adalah orang yang ...", options: ["tidak dikenal siapa pun", "tidak memiliki riwayat hidup", "memiliki prestasi, jasa, atau keistimewaan", "menolak untuk diceritakan"], answer: 2, solution: "1. Tidak semua orang ditulis riwayat hidupnya. 2. Yang layak ditulis adalah orang dengan prestasi, jasa, atau keistimewaan. 3. Kisah merekalah yang memberi teladan. 4. Jadi, tokoh biografi umumnya orang yang memiliki prestasi, jasa, atau keistimewaan." },
{ q: "Penggunaan kata ganti \"beliau\" dalam teks biografi menunjukkan ...", options: ["penghormatan penulis kepada tokoh", "kedekatan penulis dengan tokoh", "tokoh masih anak-anak", "penulis tidak mengenal tokoh"], answer: 0, solution: "1. Kata beliau adalah bentuk halus dari dia. 2. Bentuk halus dipakai untuk orang yang dihormati. 3. Pemakaiannya menunjukkan sikap hormat penulis. 4. Jadi, menunjukkan penghormatan penulis kepada tokoh." },
{ q: "Bagian orientasi dalam teks negosiasi berisi ...", options: ["kegiatan tawar-menawar", "kesepakatan kedua pihak", "salam pembuka dan pengenalan topik pembicaraan", "ucapan terima kasih dan salam penutup"], answer: 2, solution: "1. Negosiasi diawali dengan pembuka sebelum masuk ke inti. 2. Pembuka berisi salam dan pengenalan topik pembicaraan. 3. Bagian ini disebut orientasi. 4. Jadi, orientasi berisi salam pembuka dan pengenalan topik pembicaraan." },
{ q: "Bagian pengajuan dalam teks negosiasi berisi ...", options: ["penyampaian maksud, tujuan, atau permintaan salah satu pihak", "tawar-menawar harga", "persetujuan akhir", "salam perpisahan"], answer: 0, solution: "1. Setelah pembuka, salah satu pihak menyampaikan keinginannya. 2. Penyampaian maksud, tujuan, atau permintaan disebut pengajuan. 3. Tawar-menawar terjadi pada tahap penawaran. 4. Jadi, pengajuan berisi penyampaian maksud, tujuan, atau permintaan salah satu pihak." },
{ q: "Bagian persetujuan dalam teks negosiasi ditandai dengan ...", options: ["pengajuan harga pertama", "kesepakatan kedua belah pihak atas hasil tawar-menawar", "perkenalan kedua pihak", "penolakan tawaran"], answer: 1, solution: "1. Tawar-menawar berakhir ketika kedua pihak sepakat. 2. Kesepakatan atas hasil tawar-menawar menandai tahap persetujuan. 3. Pengajuan harga pertama terjadi pada tahap penawaran. 4. Jadi, persetujuan ditandai dengan kesepakatan kedua belah pihak atas hasil tawar-menawar." },
{ q: "Bagian penutup teks negosiasi berisi ...", options: ["tawar-menawar harga", "pengajuan permintaan", "perkenalan penjual", "salam penutup dan ucapan terima kasih"], answer: 3, solution: "1. Negosiasi diakhiri dengan bagian penutup. 2. Penutup berisi salam perpisahan dan ucapan terima kasih. 3. Tawar-menawar dan pengajuan terjadi pada tahap sebelumnya. 4. Jadi, penutup berisi salam penutup dan ucapan terima kasih." },
{ q: "Urutan struktur teks negosiasi yang tepat adalah ...", options: ["orientasi - pengajuan - penawaran - persetujuan - penutup", "penutup - orientasi - pengajuan - penawaran - persetujuan", "pengajuan - orientasi - persetujuan - penawaran - penutup", "penawaran - pengajuan - orientasi - penutup - persetujuan"], answer: 0, solution: "1. Negosiasi dimulai dengan orientasi sebagai pembuka. 2. Dilanjutkan pengajuan maksud lalu penawaran berisi tawar-menawar. 3. Setelah sepakat tercapai persetujuan dan diakhiri penutup. 4. Jadi, urutan yang tepat adalah orientasi - pengajuan - penawaran - persetujuan - penutup." },
{ q: "Agar tercapai win-win solution dalam negosiasi, kedua belah pihak harus ...", options: ["bersikeras pada pendiriannya", "saling menekan lawan bicara", "bersedia berkompromi dan tidak egois", "membatalkan negosiasi"], answer: 2, solution: "1. Win-win solution berarti kedua pihak sama-sama untung. 2. Keuntungan bersama tidak tercapai jika masing-masing bersikeras. 3. Diperlukan kesediaan berkompromi dan sikap tidak egois. 4. Jadi, kedua pihak harus bersedia berkompromi dan tidak egois." },
{ q: "Kalimat persuasif dalam teks negosiasi bertujuan ...", options: ["memerintah mitra dengan kasar", "membujuk dan meyakinkan mitra agar menerima tawaran", "menceritakan pengalaman pribadi", "menjelaskan langkah kerja"], answer: 1, solution: "1. Persuasif berasal dari kata persuasi yang berarti bujukan. 2. Dalam negosiasi, kalimat persuasif dipakai untuk memengaruhi mitra. 3. Tujuannya agar mitra yakin dan menerima tawaran. 4. Jadi, kalimat persuasif bertujuan membujuk dan meyakinkan mitra agar menerima tawaran." },
{ q: "Manakah kalimat berikut yang bersifat persuasif?", options: ["Toko ini buka setiap hari.", "Saya datang ke sini kemarin sore.", "Barang itu berwarna merah.", "Harga ini sudah termasuk garansi satu tahun, jadi Bapak tidak perlu khawatir."], answer: 3, solution: "1. Kalimat persuasif membujuk dengan memberi alasan meyakinkan. 2. Pilihan keempat menawarkan rasa aman lewat garansi satu tahun. 3. Tiga pilihan lain hanya memberi informasi biasa. 4. Jadi, yang bersifat persuasif adalah kalimat tentang garansi satu tahun." },
{ q: "Manakah contoh kalimat penawaran dalam teks negosiasi?", options: ["Bagaimana kalau harganya saya turunkan menjadi Rp45 ribu?", "Selamat pagi, Pak.", "Terima kasih atas waktunya.", "Baik, saya setuju."], answer: 0, solution: "1. Kalimat penawaran berisi ajuan harga atau syarat. 2. \"Bagaimana kalau harganya saya turunkan menjadi Rp45 ribu?\" mengajukan harga baru. 3. Pilihan lain adalah salam, terima kasih, dan persetujuan. 4. Jadi, contoh kalimat penawaran adalah ajuan penurunan harga tersebut." },
{ q: "Ciri kalimat penawaran dalam negosiasi adalah ...", options: ["berisi salam pembuka", "berisi ucapan terima kasih", "berisi ajuan harga atau syarat sebagai bahan tawar-menawar", "berisi penolakan mutlak"], answer: 2, solution: "1. Tahap penawaran adalah tahap tawar-menawar. 2. Kalimat pada tahap ini berisi ajuan harga atau syarat. 3. Ajuan itu menjadi bahan tawar-menawar kedua pihak. 4. Jadi, cirinya adalah berisi ajuan harga atau syarat sebagai bahan tawar-menawar." },
{ q: "Prinsip kesantunan dalam bernegosiasi menuntut pembicara untuk ...", options: ["menekan lawan bicara agar menyerah", "menggunakan bahasa yang sopan dan tidak memaksa", "berbicara dengan nada tinggi", "memotong pembicaraan mitra"], answer: 1, solution: "1. Negosiasi melibatkan dua pihak yang kepentingannya berbeda. 2. Agar lancar, pembicaraan harus dijaga kesopanannya. 3. Kesantunan menuntut bahasa sopan dan tidak memaksa. 4. Jadi, pembicara harus menggunakan bahasa yang sopan dan tidak memaksa." },
{ q: "Manakah tuturan berikut yang mencerminkan kesantunan dalam negosiasi?", options: ["Maaf, Pak, bolehkah saya menawar sedikit?", "Turunkan harganya sekarang juga!", "Kalau tidak mau ya sudah, rugi sendiri!", "Harga segitu kemahalan, keterlaluan!"], answer: 0, solution: "1. Tuturan santun memakai kata maaf dan bahasa halus. 2. \"Maaf, Pak, bolehkah saya menawar sedikit?\" memakai kata maaf dan bertanya dengan halus. 3. Tiga pilihan lain bernada kasar dan memaksa. 4. Jadi, yang mencerminkan kesantunan adalah tuturan pertama." },
{ q: "Sebelum melakukan negosiasi jual beli, hal penting yang perlu disiapkan pembeli adalah ...", options: ["membawa pengeras suara", "menghafal nama penjual", "menyiapkan ancaman", "mengetahui harga pasaran barang tersebut"], answer: 3, solution: "1. Pembeli yang tidak tahu harga mudah dipermainkan. 2. Mengetahui harga pasaran memberi patokan menawar. 3. Inilah persiapan penting sebelum negosiasi. 4. Jadi, yang perlu disiapkan adalah mengetahui harga pasaran barang tersebut." },
{ q: "Manakah contoh kalimat pengajuan dalam teks negosiasi?", options: ["Harganya bisa kurang sedikit, Pak?", "Deal, saya ambil semuanya.", "Saya ingin membeli sepuluh karung beras untuk acara desa.", "Terima kasih banyak, Pak."], answer: 2, solution: "1. Pengajuan adalah penyampaian maksud atau permintaan. 2. \"Saya ingin membeli sepuluh karung beras untuk acara desa\" menyampaikan maksud membeli. 3. Pilihan lain adalah penawaran, persetujuan, dan penutup. 4. Jadi, contoh kalimat pengajuan adalah pernyataan ingin membeli tersebut." },
{ q: "Manakah contoh kalimat persetujuan dalam teks negosiasi?", options: ["Berapa harga pasnya?", "Baiklah, saya setuju dengan harga tersebut.", "Saya tawar Rp40 ribu, bagaimana?", "Selamat siang, Pak."], answer: 1, solution: "1. Persetujuan adalah pernyataan sepakat atas hasil tawar-menawar. 2. \"Baiklah, saya setuju dengan harga tersebut\" menyatakan kesepakatan. 3. Pilihan lain adalah salam, penawaran, dan pertanyaan harga. 4. Jadi, contoh kalimat persetujuan adalah pernyataan setuju tersebut." },
{ q: "Manakah contoh kalimat penutup dalam teks negosiasi?", options: ["Terima kasih atas kesediaannya, sampai jumpa.", "Saya mau menawar barang ini.", "Harganya terlalu mahal bagi saya.", "Saya setuju dengan tawaran Anda."], answer: 0, solution: "1. Penutup mengakhiri negosiasi dengan salam dan terima kasih. 2. \"Terima kasih atas kesediaannya, sampai jumpa\" memuat keduanya. 3. Pilihan lain adalah penawaran, keluhan harga, dan persetujuan. 4. Jadi, contoh kalimat penutup adalah ucapan terima kasih dan sampai jumpa tersebut." },
{ q: "Pihak-pihak yang terlibat dalam negosiasi jual beli di pasar adalah ...", options: ["guru dan murid", "dokter dan pasien", "hakim dan terdakwa", "penjual dan pembeli"], answer: 3, solution: "1. Negosiasi jual beli di pasar melibatkan dua kepentingan. 2. Satu pihak menjual barang dan satu pihak membeli. 3. Keduanya disebut penjual dan pembeli. 4. Jadi, pihak yang terlibat adalah penjual dan pembeli." },
{ q: "Penggunaan kata \"tolong\", \"maaf\", dan \"terima kasih\" dalam negosiasi menunjukkan ...", options: ["kelemahan pendirian", "ketidaktahuan topik", "kesantunan berbahasa", "kemarahan pembicara"], answer: 2, solution: "1. Kata tolong, maaf, dan terima kasih adalah kata-kata santun. 2. Pemakaiannya menunjukkan pembicara menjaga sopan santun. 3. Inilah wujud kesantunan berbahasa dalam negosiasi. 4. Jadi, menunjukkan kesantunan berbahasa." },
{ q: "Taktik yang tepat ketika tawaran kita ditolak dalam negosiasi adalah ...", options: ["langsung pergi meninggalkan tempat", "mengajukan tawaran alternatif yang lebih menguntungkan kedua pihak", "memaksa dengan nada tinggi", "membatalkan semua pembicaraan"], answer: 1, solution: "1. Penolakan tawaran bukan akhir negosiasi. 2. Pihak yang bijak tidak langsung pergi atau memaksa. 3. Ia mengajukan tawaran alternatif yang menguntungkan kedua pihak. 4. Jadi, taktik yang tepat adalah mengajukan tawaran alternatif yang lebih menguntungkan kedua pihak." },
{ q: "Kalimat persuasif menjadi efektif dalam negosiasi apabila ...", options: ["disertai alasan yang logis dan menguntungkan mitra", "diucapkan dengan berteriak", "tanpa disertai alasan apa pun", "berisi ancaman terselubung"], answer: 0, solution: "1. Bujukan tanpa alasan sulit dipercaya mitra. 2. Alasan yang logis membuat tawaran masuk akal. 3. Keuntungan bagi mitra membuat tawaran menarik. 4. Jadi, kalimat persuasif efektif apabila disertai alasan yang logis dan menguntungkan mitra." }
,
{ q: "Perhatikan larik berikut: \"Engkau pelita di lorong gelap hidupku.\" Majas yang digunakan pada larik tersebut adalah…", options: ["Personifikasi", "Metafora", "Simile", "Hiperbola"], answer: 1, solution: "1. Larik membandingkan \"engkau\" dengan \"pelita\" secara langsung. 2. Tidak ada kata pembanding seperti \"seperti\" atau \"bagai\". 3. Perbandingan langsung tanpa kata pembanding disebut metafora." },
{ q: "Larik \"Angin malam berbisik lirih di telingaku\" mengandung majas…", options: ["Metafora", "Simile", "Personifikasi", "Ironi"], answer: 2, solution: "1. Angin adalah benda mati yang tidak bisa berbicara. 2. Pada larik, angin digambarkan \"berbisik lirih\" seperti manusia. 3. Pemberian sifat manusia pada benda mati disebut personifikasi." },
{ q: "\"Tangisnya mampu menenggelamkan seluruh kota dalam sekejap.\" Majas pada kalimat tersebut adalah…", options: ["Hiperbola", "Metafora", "Paradoks", "Litotes"], answer: 0, solution: "1. Kalimat melebih-lebihkan kenyataan secara ekstrem. 2. Tangis manusia tidak mungkin menenggelamkan sebuah kota. 3. Ungkapan yang dilebih-lebihkan secara berlebihan disebut hiperbola." },
{ q: "\"Senyumnya manis bagaikan madu di pagi hari.\" Kata pembanding pada larik tersebut menunjukkan majas…", options: ["Metafora", "Simile", "Personifikasi", "Alegori"], answer: 1, solution: "1. Ada kata pembanding \"bagaikan\" pada larik. 2. Senyum dibandingkan dengan madu memakai kata pembanding. 3. Perbandingan yang memakai kata seperti, bagai, bak, atau laksana disebut simile." },
{ q: "\"Di tengah keramaian pesta itu, hatiku justru terasa paling sepi.\" Majas yang tepat untuk larik tersebut adalah…", options: ["Ironi", "Hiperbola", "Paradoks", "Sinekdoke"], answer: 2, solution: "1. Kata \"ramai\" dan \"sepi\" tampak bertentangan. 2. Namun keduanya bisa benar sekaligus: ramai suasananya, sepi perasaannya. 3. Pernyataan yang tampak bertentangan tetapi mengandung kebenaran disebut paradoks." },
{ q: "\"Wah, rajin sekali kamu sampai tugasmu tidak ada satu pun yang dikumpulkan.\" Majas pada kalimat tersebut adalah…", options: ["Ironi", "Sarkasme", "Hiperbola", "Paradoks"], answer: 0, solution: "1. Kata \"rajin\" bertolak belakang dengan fakta \"tugas tidak dikumpulkan\". 2. Makna sebenarnya berlawanan dengan kata yang diucapkan, disampaikan secara halus. 3. Sindiran halus dengan makna berlawanan disebut ironi." },
{ q: "\"Panitia menyediakan nasi bungkus untuk lima ratus perut yang hadir.\" Kata \"perut\" pada kalimat tersebut merupakan contoh majas…", options: ["Metonimia", "Sinekdoke", "Metafora", "Simile"], answer: 1, solution: "1. \"Perut\" hanyalah sebagian dari tubuh manusia. 2. Kata itu dipakai untuk menyebut keseluruhan orang yang hadir. 3. Menyebut sebagian untuk keseluruhan (pars pro toto) disebut sinekdoke." },
{ q: "\"Sejak kecil ia gemar membaca Pramoedya hingga larut malam.\" Kata \"Pramoedya\" pada kalimat tersebut merupakan contoh majas…", options: ["Sinekdoke", "Metonimia", "Personifikasi", "Alegori"], answer: 1, solution: "1. Yang dibaca tentu bukan orangnya, melainkan karya-karyanya. 2. Nama pengarang dipakai untuk menggantikan nama karyanya. 3. Penyebutan suatu nama untuk menggantikan hal yang berkaitan erat dengannya disebut metonimia." },
{ q: "Seluruh bait sebuah puisi menggambarkan perjalanan kapal menembus badai sebagai kiasan perjalanan hidup manusia. Gaya bahasa seperti ini disebut…", options: ["Metafora", "Alegori", "Simile", "Paradoks"], answer: 1, solution: "1. Kiasan \"kapal\" dan \"badai\" dipakai secara berkelanjutan sepanjang bait. 2. Ini bukan satu perbandingan sesaat, melainkan jalinan cerita kiasan yang utuh. 3. Kiasan yang dijalin berkesinambungan disebut alegori." },
{ q: "\"Sunyi sepi senja menyelimuti sawah yang sendu.\" Unsur bunyi yang menonjol pada larik tersebut adalah…", options: ["Asonansi", "Aliterasi", "Rima akhir", "Onomatope"], answer: 1, solution: "1. Bunyi konsonan \"s\" berulang: sunyi, sepi, senja, menyelimuti, sawah, sendu. 2. Terjadi pengulangan bunyi konsonan pada kata-kata yang berurutan. 3. Pengulangan bunyi konsonan disebut aliterasi." },
{ q: "\"Gemuruh petir menyobek langit, disusul deru hujan yang menderas.\" Citraan yang dominan pada larik tersebut adalah citraan…", options: ["Penglihatan", "Pendengaran", "Perabaan", "Penciuman"], answer: 1, solution: "1. Kata \"gemuruh\", \"menyobek\", dan \"deru\" berkaitan dengan bunyi. 2. Pembaca diajak seolah-olah mendengar suasana badai lewat kata-kata itu. 3. Citraan yang merangsang indra pendengaran disebut citraan auditif." },
{ q: "\"Mentari terbenam memerahkan cakrawala, perahu-perahu kecil berlayar pulang.\" Citraan yang menonjol pada larik tersebut adalah…", options: ["Citraan gerak", "Citraan penglihatan", "Citraan perabaan", "Citraan intelektual"], answer: 1, solution: "1. Kata \"memerahkan cakrawala\" dan \"perahu-perahu kecil\" menghadirkan gambaran yang bisa dilihat. 2. Pembaca seolah-olah melihat lukisan senja di depan mata. 3. Citraan yang merangsang indra penglihatan disebut citraan visual." },
{ q: "\"Ia berhati baja menghadapi segala cobaan.\" Kata \"baja\" pada larik tersebut bermakna…", options: ["Denotasi: logam yang keras", "Konotasi: tegar dan pantang menyerah", "Denotasi: senjata yang tajam", "Konotasi: dingin dan kejam"], answer: 1, solution: "1. Secara harfiah baja memang logam yang keras, itu makna denotasi. 2. Dalam larik, \"hati baja\" dipakai untuk menggambarkan sifat tegar menghadapi cobaan. 3. Makna tambahan di luar makna harfiah disebut makna konotasi." },
{ q: "Bacalah bait berikut: \"Ibu, engkaulah mentari pagiku / Doamu perisai dalam langkahku / Kasihmu seluas samudra biru.\" Tema puisi tersebut adalah…", options: ["Keindahan alam", "Kasih sayang seorang ibu", "Perjuangan hidup", "Kerinduan pada kampung halaman"], answer: 1, solution: "1. Seluruh larik berpusat pada sosok \"ibu\". 2. Diksi \"kasihmu\" dan \"doamu\" menegaskan hubungan anak dan ibu. 3. Gagasan pokok yang melandasi keseluruhan puisi disebut tema." },
{ q: "\"Jangan biarkan waktumu berlalu sia-sia / Esok belum tentu mentari menyapa / Berkaryalah selagi napas masih ada.\" Amanat puisi tersebut adalah…", options: ["Manfaatkan waktu sebaik-baiknya", "Jangan takut pada kegelapan", "Hargai keindahan mentari", "Istirahatlah selagi bisa"], answer: 0, solution: "1. Larik berisi ajakan \"berkaryalah selagi napas masih ada\". 2. Pesan yang ingin disampaikan penyair bersifat nasihat bagi pembaca. 3. Pesan moral yang ingin disampaikan penyair disebut amanat." },
{ q: "Sebuah puisi disusun dengan larik-larik yang membentuk gambar layang-layang di halaman. Unsur puisi yang dieksploitasi penyair tersebut adalah…", options: ["Rima", "Tipografi", "Diksi", "Irama"], answer: 1, solution: "1. Susunan larik membentuk pola visual menyerupai layang-layang. 2. Yang dimainkan adalah bentuk penulisan puisi di halaman. 3. Bentuk susunan baris dan bait puisi disebut tipografi." },
{ q: "Ciri yang membedakan puisi lama seperti pantun dan syair dari puisi kontemporer adalah…", options: ["Puisi lama terikat jumlah larik, rima, dan bait", "Puisi lama selalu bertema percintaan", "Puisi kontemporer wajib memakai bahasa daerah", "Puisi lama tidak memiliki amanat"], answer: 0, solution: "1. Pantun terikat empat larik dengan pola rima a-b-a-b. 2. Syair terikat bait empat larik dengan rima a-a-a-a. 3. Keterikatan pada aturan bait, larik, dan rima adalah ciri puisi lama." },
{ q: "Larik-larik sebuah puisi berakhiran bunyi yang sama: \"pagi\", \"mentari\", \"bernyanyi\", \"berseri\". Pola rima tersebut adalah rima…", options: ["Rima silang", "Rima rata", "Rima peluk", "Rima bebas"], answer: 1, solution: "1. Semua akhir larik berbunyi sama, polanya a-a-a-a. 2. Tidak ada variasi silang (a-b-a-b) atau peluk (a-b-b-a). 3. Rima dengan bunyi akhir yang sama semua disebut rima rata." },
{ q: "\"Indonesia akhirnya mengalahkan Thailand dengan skor 2-1.\" Kata \"Indonesia\" pada kalimat tersebut merupakan contoh majas…", options: ["Metonimia", "Sinekdoke", "Hiperbola", "Personifikasi"], answer: 1, solution: "1. Yang bertanding bukan seluruh negara, melainkan tim sepak bolanya. 2. Keseluruhan (negara) dipakai untuk menyebut sebagian (tim). 3. Menyebut keseluruhan untuk sebagian (totum pro parte) disebut sinekdoke." },
{ q: "Pasangan kalimat yang tepat menunjukkan perbedaan metafora dan simile adalah…", options: ["\"Ia singa podium\" (metafora) – \"Ia seperti singa di podium\" (simile)", "\"Ia seperti singa\" (metafora) – \"Ia singa podium\" (simile)", "Keduanya metafora karena memakai nama hewan", "Keduanya simile karena membandingkan dua hal"], answer: 0, solution: "1. \"Ia singa podium\" membandingkan secara langsung tanpa kata pembanding, jadi metafora. 2. \"Ia seperti singa di podium\" memakai kata \"seperti\", jadi simile. 3. Perbedaan keduanya terletak pada ada atau tidaknya kata pembanding." },
{ q: "\"Ombak berkejaran menuju pantai, buihnya menari-nari di udara.\" Citraan yang dominan pada larik tersebut adalah…", options: ["Citraan penglihatan", "Citraan gerak", "Citraan penciuman", "Citraan perabaan"], answer: 1, solution: "1. Kata \"berkejaran\" dan \"menari-nari\" menggambarkan gerakan. 2. Pembaca diajak merasakan gerak ombak dan buih. 3. Citraan yang menggambarkan gerak disebut citraan kinestetik atau citraan gerak." },
{ q: "Kata-kata seperti \"nirmala\", \"waskita\", dan \"asmaradana\" lazim ditemukan dalam puisi lama. Kata-kata tersebut termasuk…", options: ["Kata serapan modern", "Kata arkais", "Kata slang", "Kata konkret kontemporer"], answer: 1, solution: "1. Kata-kata itu sudah jarang dipakai dalam percakapan sehari-hari. 2. Kata lama yang tidak lagi lazim dipakai disebut kata arkais. 3. Puisi lama memang kaya akan diksi arkais." },
{ q: "Perbedaan tema dan amanat dalam puisi terletak pada…", options: ["Tema adalah pesan moral, amanat adalah gagasan pokok", "Tema adalah gagasan pokok, amanat adalah pesan yang ingin disampaikan", "Keduanya sama persis tanpa perbedaan", "Tema hanya ada dalam puisi lama"], answer: 1, solution: "1. Tema menjawab pertanyaan \"puisi ini tentang apa\". 2. Amanat menjawab pertanyaan \"pesan apa yang ingin disampaikan\". 3. Tema adalah gagasan pokok, sedangkan amanat adalah pesan moral." },
{ q: "Ciri puisi kontemporer yang paling menonjol dibandingkan puisi lama adalah…", options: ["Wajib terdiri atas empat bait", "Bebas dari keterikatan rima, jumlah larik, dan bait", "Selalu memakai bahasa Melayu klasik", "Tidak boleh memiliki tema"], answer: 1, solution: "1. Puisi kontemporer tidak terikat aturan jumlah bait dan rima. 2. Penyair bebas bereksperimen dengan bentuk, diksi, dan tipografi. 3. Kebebasan bentuk inilah ciri utama puisi kontemporer." },
{ q: "\"Derai hujan di atas genting / Mengetuk-ngetuk tanpa henti.\" Kesan musikal yang timbul dari pengulangan bunyi tersebut berkaitan dengan unsur…", options: ["Diksi", "Irama", "Tema", "Tipografi"], answer: 1, solution: "1. Pengulangan bunyi menciptakan alunan yang teratur dan merdu. 2. Alunan bunyi yang naik-turun dalam puisi itulah irama. 3. Keteraturan bunyi yang menimbulkan kemerduan disebut irama." },
{ q: "Bagian resensi yang memuat judul buku, nama pengarang, penerbit, tahun terbit, dan tebal halaman disebut…", options: ["Sinopsis", "Identitas karya", "Evaluasi", "Orientasi"], answer: 1, solution: "1. Data judul, pengarang, penerbit, tahun, dan tebal halaman adalah data fisik buku. 2. Data ini memperkenalkan karya yang akan diresensi. 3. Bagian yang berisi data karya disebut identitas karya." },
{ q: "Fungsi utama sinopsis dalam sebuah resensi adalah…", options: ["Menilai kelebihan dan kekurangan karya", "Meringkas isi karya secara garis besar", "Menyimpulkan rekomendasi bagi pembaca", "Mengutip seluruh isi karya"], answer: 1, solution: "1. Sinopsis memberi gambaran isi tanpa mengupas karya sampai tuntas. 2. Pembaca jadi tahu garis besar cerita sebelum membaca karya aslinya. 3. Ringkasan isi karya secara garis besar disebut sinopsis." },
{ q: "\"Novel ini sangat layak dibaca para remaja karena bahasanya ringan dan sarat pesan moral.\" Kalimat tersebut terdapat pada bagian…", options: ["Sinopsis", "Identitas karya", "Evaluasi", "Orientasi"], answer: 2, solution: "1. Kalimat berisi penilaian \"sangat layak dibaca\". 2. Ada rekomendasi yang ditujukan untuk kelompok pembaca tertentu. 3. Penilaian akhir beserta rekomendasi terdapat pada bagian evaluasi." },
{ q: "Pembahasan tokoh, alur, latar, dan sudut pandang dalam resensi novel termasuk pembahasan unsur…", options: ["Ekstrinsik", "Intrinsik", "Kebahasaan", "Tipografi"], answer: 1, solution: "1. Tokoh, alur, latar, dan sudut pandang berada di dalam karya. 2. Unsur-unsur itu membangun karya dari dalam. 3. Unsur pembangun karya dari dalam disebut unsur intrinsik." },
{ q: "Latar belakang kehidupan pengarang dan kondisi sosial saat karya ditulis termasuk unsur…", options: ["Intrinsik", "Ekstrinsik", "Struktural", "Estetis"], answer: 1, solution: "1. Biografi pengarang berada di luar teks karya. 2. Kondisi sosial juga merupakan faktor luar yang memengaruhi karya. 3. Unsur yang berada di luar karya disebut unsur ekstrinsik." },
{ q: "Perhatikan kalimat: \"Film ini menyuguhkan visual yang memukau dan alur yang menegangkan.\" Kata yang bercetak miring termasuk…", options: ["Kata kerja material", "Kata sifat sikap", "Kata ganti orang", "Kata bilangan"], answer: 1, solution: "1. Kata \"memukau\" dan \"menegangkan\" menyatakan penilaian peresensi. 2. Kata-kata itu mengungkapkan sikap terhadap karya yang diresensi. 3. Kata sifat yang menyatakan sikap penilai disebut kata sifat sikap." },
{ q: "Kalimat yang tepat untuk menyampaikan saran dalam resensi adalah…", options: ["\"Penulis sebaiknya memperdalam konflik tokoh utama agar lebih hidup.\"", "\"Buku ini terbit tahun 2024 dengan tebal 300 halaman.\"", "\"Novel ini bercerita tentang petualangan lima sekawan.\"", "\"Harga buku ini cukup terjangkau bagi pelajar.\""], answer: 0, solution: "1. Kalimat memakai kata \"sebaiknya\" yang bersifat anjuran. 2. Isinya berupa usulan perbaikan yang ditujukan kepada penulis. 3. Kalimat yang berisi anjuran perbaikan disebut kalimat saran." },
{ q: "Tujuan utama menulis resensi adalah…", options: ["Menceritakan kembali seluruh isi karya", "Memberi pertimbangan kepada pembaca sebelum menikmati karya", "Menggantikan karya asli agar tak perlu dibaca", "Mengkritik pribadi pengarangnya"], answer: 1, solution: "1. Resensi berisi penilaian atas kelebihan dan kekurangan karya. 2. Penilaian itu membantu calon pembaca atau penonton memutuskan. 3. Memberi bahan pertimbangan adalah tujuan utama resensi." },
{ q: "Bagian identitas dalam resensi film umumnya memuat…", options: ["Judul, sutradara, durasi, genre, dan tahun rilis", "Seluruh dialog para pemain", "Daftar kru bagian katering", "Harga tiket di setiap bioskop"], answer: 0, solution: "1. Resensi film memerlukan data pokok tentang film tersebut. 2. Judul, sutradara, durasi, genre, dan tahun rilis adalah data pokok film. 3. Data pokok film dimuat pada bagian identitas karya." },
{ q: "Perbedaan resensi dan sinopsis terletak pada…", options: ["Sinopsis menilai karya, resensi meringkas isi", "Resensi memuat penilaian, sinopsis hanya meringkas isi", "Keduanya sama persis tanpa perbedaan", "Resensi tidak boleh memuat sinopsis"], answer: 1, solution: "1. Sinopsis berhenti pada ringkasan isi karya. 2. Resensi melangkah lebih jauh dengan menilai dan merekomendasikan. 3. Ada atau tidaknya penilaian inilah pembeda keduanya." },
{ q: "\"Kelemahan novel ini terletak pada alur yang lambat di sepertiga awal.\" Kalimat tersebut menunjukkan…", options: ["Keunggulan karya", "Kelemahan karya", "Identitas karya", "Sinopsis karya"], answer: 1, solution: "1. Kata \"kelemahan\" menandai sisi yang kurang dari karya. 2. Alur yang lambat dipandang sebagai kekurangan novel tersebut. 3. Penilaian terhadap sisi kurang disebut kelemahan karya." },
{ q: "\"Gaya bahasa penulis yang puitis membuat setiap bab terasa hidup.\" Kalimat tersebut menunjukkan…", options: ["Kelemahan karya", "Sinopsis", "Keunggulan karya", "Saran perbaikan"], answer: 2, solution: "1. Gaya bahasa yang puitis dipuji sebagai nilai lebih. 2. Frasa \"terasa hidup\" adalah penilaian yang positif. 3. Penilaian terhadap sisi lebih disebut keunggulan karya." },
{ q: "Ciri bahasa resensi yang baik adalah…", options: ["Berbelit-belit agar terkesan ilmiah", "Lugas, jelas, dan didukung alasan penilaian", "Penuh singkatan tanpa penjelasan", "Hanya berisi pujian tanpa kritik"], answer: 1, solution: "1. Resensi bertujuan memberi pertimbangan yang objektif. 2. Setiap penilaian harus jelas dan disertai alasan. 3. Bahasa yang lugas dan beralasan adalah ciri bahasa resensi yang baik." },
{ q: "Langkah pertama yang tepat sebelum menulis resensi adalah…", options: ["Langsung menulis penilaian tanpa membaca karya", "Membaca atau menonton karya secara cermat dan mencatat hal penting", "Menyalin resensi orang lain", "Menebak isi karya dari sampulnya saja"], answer: 1, solution: "1. Penilaian harus berdasar pada karya yang utuh, bukan tebakan. 2. Catatan membantu mengingat detail penting selama membaca. 3. Membaca cermat disertai mencatat adalah langkah awal yang tepat." },
{ q: "Sudut pandang \"aku\" yang dipakai pengarang dalam novel termasuk unsur…", options: ["Ekstrinsik", "Intrinsik", "Kebahasaan resensi", "Identitas karya"], answer: 1, solution: "1. Sudut pandang adalah cara pengarang menempatkan diri dalam cerita. 2. Ia ikut membangun cerita dari dalam karya. 3. Unsur pembangun karya dari dalam disebut unsur intrinsik." },
{ q: "Manakah kalimat yang menggunakan kata sifat sikap secara tepat dalam resensi?", options: ["\"Buku ini memiliki 250 halaman.\"", "\"Buku ini terbit di Jakarta.\"", "\"Buku ini menyajikan kisah yang mengharukan.\"", "\"Buku ini ditulis oleh dua orang.\""], answer: 2, solution: "1. Kata \"mengharukan\" menyatakan sikap dan kesan peresensi. 2. Pilihan lain hanya menyatakan fakta tanpa penilaian. 3. Kata yang menyatakan sikap penilai disebut kata sifat sikap." },
{ q: "Bagian orientasi dalam resensi berisi…", options: ["Penilaian akhir terhadap karya", "Gambaran umum atau pengantar tentang karya yang diresensi", "Daftar pustaka", "Biodata peresensi"], answer: 1, solution: "1. Orientasi membuka resensi sebelum masuk ke pembahasan isi. 2. Isinya berupa pengantar umum tentang karya yang diresensi. 3. Pengantar umum tentang karya disebut orientasi." },
{ q: "Hal yang tidak boleh dilakukan oleh seorang peresensi adalah…", options: ["Menilai dengan alasan yang jelas", "Menjiplak resensi orang lain tanpa mencantumkan sumber", "Menyampaikan kelebihan dan kekurangan", "Memberi rekomendasi kepada pembaca"], answer: 1, solution: "1. Menjiplak karya orang lain termasuk plagiarisme. 2. Resensi harus orisinal, jujur, dan berdasarkan pengamatan sendiri. 3. Plagiarisme adalah hal yang dilarang dalam menulis resensi." },
{ q: "\"Bagi penggemar misteri, film ini wajib masuk daftar tontonan akhir pekan.\" Kalimat tersebut berfungsi sebagai…", options: ["Sinopsis", "Rekomendasi pada bagian evaluasi", "Identitas karya", "Kutipan dialog film"], answer: 1, solution: "1. Kalimat mengajak kelompok penonton tertentu untuk menonton. 2. Ajakan menonton adalah bentuk rekomendasi. 3. Rekomendasi kepada pembaca terdapat pada bagian evaluasi." },
{ q: "Unsur ekstrinsik yang tepat dianalisis dalam resensi novel berlatar perang adalah…", options: ["Jumlah bab dalam novel", "Kondisi sosial politik saat novel ditulis", "Jenis huruf yang dipakai", "Harga buku di pasaran"], answer: 1, solution: "1. Latar perang berkaitan erat dengan kondisi zaman penulisan. 2. Kondisi sosial politik adalah faktor di luar karya. 3. Faktor di luar karya yang memengaruhi isi disebut unsur ekstrinsik." },
{ q: "Kaidah kebahasaan resensi tampak pada kalimat \"Sebaiknya sutradara memangkas durasi bagian tengah film.\" Kalimat tersebut termasuk…", options: ["Kalimat definisi", "Kalimat saran", "Kalimat perintah kasar", "Kalimat tanya retoris"], answer: 1, solution: "1. Kata \"sebaiknya\" menandai sifat anjuran. 2. Anjuran itu berupa usulan perbaikan bagi pembuat karya. 3. Kalimat yang berisi anjuran perbaikan disebut kalimat saran." },
{ q: "Sinopsis yang baik dalam sebuah resensi hendaknya…", options: ["Mengungkap seluruh akhir cerita secara detail", "Meringkas isi tanpa membocorkan seluruh kejutan cerita", "Menyalin blurb sampul belakang kata per kata", "Hanya berisi penilaian peresensi"], answer: 1, solution: "1. Sinopsis memberi gambaran, bukan menggantikan karya aslinya. 2. Kejutan cerita perlu dijaga agar pembaca tetap penasaran. 3. Meringkas tanpa membocorkan semuanya adalah sinopsis yang baik." },
{ q: "Struktur resensi yang tepat secara berurutan adalah…", options: ["Evaluasi – sinopsis – identitas – orientasi", "Identitas – orientasi – sinopsis – analisis – evaluasi", "Sinopsis – evaluasi – identitas – analisis", "Orientasi – evaluasi – sinopsis – identitas"], answer: 1, solution: "1. Resensi dibuka dengan data karya, yaitu identitas. 2. Dilanjutkan pengantar (orientasi), ringkasan (sinopsis), lalu pembahasan (analisis). 3. Ditutup dengan penilaian (evaluasi). Itulah urutan yang tepat." },
{ q: "Dalam resensi film, pembahasan akting pemain dan kualitas sinematografi termasuk…", options: ["Identitas karya", "Analisis unsur karya", "Sinopsis", "Orientasi"], answer: 1, solution: "1. Akting dan sinematografi adalah unsur pembangun film. 2. Membahas unsur-unsur pembangun karya adalah analisis. 3. Pembahasan akting dan sinematografi termasuk analisis unsur karya." },
{ q: "Nada yang tepat saat menyampaikan kelemahan karya dalam resensi adalah…", options: ["Menyindir pribadi pengarangnya", "Santun dan membangun dengan alasan yang jelas", "Melebih-lebihkan kekurangan karya", "Mengabaikan kelebihan karya sama sekali"], answer: 1, solution: "1. Kritik bertujuan memperbaiki karya, bukan menjatuhkan pengarang. 2. Bahasa yang santun menjaga objektivitas peresensi. 3. Kritik yang santun, membangun, dan beralasan adalah nada yang tepat." },
{ q: "Bagian pendahuluan karya ilmiah umumnya memuat…", options: ["Simpulan dan saran", "Latar belakang, rumusan masalah, dan tujuan penelitian", "Daftar pustaka", "Lampiran data mentah"], answer: 1, solution: "1. Pendahuluan berfungsi membuka dan memberi arah penelitian. 2. Latar belakang, rumusan masalah, dan tujuan adalah fondasi arah tersebut. 3. Ketiganya dimuat pada bagian pendahuluan." },
{ q: "Bagian penutup karya ilmiah berisi…", options: ["Latar belakang masalah", "Simpulan dan saran", "Landasan teori", "Metode penelitian"], answer: 1, solution: "1. Penutup berfungsi mengakhiri seluruh pembahasan. 2. Hasil akhir penelitian dirumuskan sebagai simpulan. 3. Tindak lanjut yang diusulkan dirumuskan sebagai saran." },
{ q: "\"Menurut Santoso (2023), literasi digital memengaruhi prestasi belajar siswa.\" Kutipan tersebut termasuk kutipan…", options: ["Langsung", "Tidak langsung", "Catatan kaki", "Daftar pustaka"], answer: 1, solution: "1. Kalimat ditulis ulang dengan bahasa penulis, bukan kata per kata. 2. Kutipan tidak diapit tanda petik. 3. Parafrase dengan tetap menyebut sumber disebut kutipan tidak langsung." },
{ q: "Perhatikan kutipan: \"Literasi adalah kemampuan memahami informasi\" (Wijaya, 2022, hlm. 45). Ciri kutipan langsung pada contoh tersebut adalah…", options: ["Ditulis dengan bahasa penulis sendiri", "Diambil kata per kata dan diapit tanda petik", "Tidak perlu mencantumkan sumber", "Hanya mencantumkan tahun terbit"], answer: 1, solution: "1. Kalimat diambil persis sama seperti di sumber aslinya. 2. Kalimat diapit tanda petik dua. 3. Pengambilan kata per kata dengan tanda petik adalah ciri kutipan langsung." },
{ q: "Penulisan daftar pustaka yang tepat menurut format APA untuk sebuah buku adalah…", options: ["\"Ahmad Santoso. 2023. Metode Penelitian. Jakarta: Pustaka Ilmu.\"", "\"Santoso, A. (2023). Metode penelitian. Jakarta: Pustaka Ilmu.\"", "\"(2023) Santoso, A: Metode Penelitian, Pustaka Ilmu Jakarta\"", "\"Metode Penelitian – Ahmad Santoso – 2023\""], answer: 1, solution: "1. Format APA menulis nama belakang lebih dulu: Santoso, A. 2. Tahun terbit ditulis dalam kurung setelah nama. 3. Polanya: Nama, Inisial. (Tahun). Judul. Kota: Penerbit." },
{ q: "Daftar pustaka dalam karya ilmiah disusun berdasarkan…", options: ["Urutan kemunculan dalam teks", "Abjad nama pengarang", "Tahun terbit terbaru", "Jumlah halaman buku"], answer: 1, solution: "1. Pembaca mencari sumber berdasarkan nama pengarang. 2. Susunan abjad memudahkan pencarian sumber. 3. Aturan bakunya adalah abjad nama pengarang." },
{ q: "Fungsi catatan kaki dalam karya ilmiah adalah…", options: ["Menggantikan daftar pustaka", "Memberi keterangan tambahan tanpa mengganggu alur teks utama", "Menambah jumlah halaman karya", "Menyembunyikan sumber kutipan"], answer: 1, solution: "1. Keterangan tambahan diletakkan di bagian bawah halaman. 2. Teks utama tetap mengalir tanpa terpotong interupsi. 3. Memberi keterangan tambahan di kaki halaman adalah fungsi catatan kaki." },
{ q: "Penulisan huruf kapital yang tepat adalah…", options: ["\"Presiden jokowi berkunjung ke jawa tengah.\"", "\"Presiden Jokowi berkunjung ke Jawa Tengah.\"", "\"presiden Jokowi Berkunjung ke jawa tengah.\"", "\"Presiden jokowi Berkunjung Ke Jawa Tengah.\""], answer: 1, solution: "1. Nama orang \"Jokowi\" wajib memakai huruf kapital. 2. Nama geografi \"Jawa Tengah\" wajib memakai huruf kapital. 3. Nama diri orang dan nama geografi ditulis dengan huruf kapital." },
{ q: "Penggunaan tanda koma yang tepat adalah…", options: ["\"Saya membeli, buku pensil dan penghapus.\"", "\"Saya membeli buku, pensil, dan penghapus.\"", "\"Saya, membeli buku pensil dan penghapus.\"", "\"Saya membeli buku pensil, dan penghapus.\""], answer: 1, solution: "1. Tanda koma memisahkan unsur-unsur rincian. 2. Rincian \"buku, pensil, dan penghapus\" dipisahkan koma dengan benar. 3. Koma dipakai untuk memisahkan unsur rincian." },
{ q: "Penggunaan tanda titik dua yang tepat adalah…", options: ["\"Buah favoritnya: adalah mangga.\"", "\"Buah favoritnya ada tiga: mangga, apel, dan jeruk.\"", "\"Dia: pergi ke pasar kemarin.\"", "\"Harga: mahal sekali.\""], answer: 1, solution: "1. Tanda titik dua dipakai sebelum rincian atau penjelasan. 2. Setelah titik dua langsung diikuti rincian tanpa kata penghubung. 3. Memerinci sesuatu adalah fungsi tanda titik dua." },
{ q: "Kata baku yang tepat adalah…", options: ["analisa", "apotek", "nasehat", "resiko"], answer: 1, solution: "1. Bentuk baku menurut KBBI adalah \"analisis\", \"nasihat\", dan \"risiko\". 2. Kata \"apotek\" sudah sesuai dengan kaidah KBBI. 3. Kata yang sesuai kaidah bahasa Indonesia disebut kata baku." },
{ q: "Kalimat efektif adalah…", options: ["\"Para siswa-siswa naik ke atas panggung.\"", "\"Para siswa naik ke panggung.\"", "\"Siswa-siswa itu mereka naik ke atas panggung.\"", "\"Ke atas panggung para siswa-siswa naik.\""], answer: 1, solution: "1. Kata \"para\" dan bentuk ulang \"siswa-siswa\" bermakna jamak ganda. 2. Frasa \"naik ke atas\" juga mengandung pemborosan makna. 3. Kalimat yang ringkas tanpa pemborosan disebut kalimat efektif." },
{ q: "Penulisan kata \"di\" yang tepat menurut EYD adalah…", options: ["\"Mereka belajar di perpustakaan.\"", "\"Mereka belajar diperpustakaan.\"", "\"Buku itu di baca adik.\"", "\"Di mana mereka di ajar?\""], answer: 0, solution: "1. Kata \"di perpustakaan\" menunjukkan tempat, jadi ditulis terpisah. 2. Kata \"dibaca\" dan \"diajar\" adalah kata kerja pasif, jadi disambung. 3. Kata depan penunjuk tempat dipisah, sedangkan imbuhan di- disambung." },
{ q: "Kutipan langsung yang terdiri atas lebih dari empat baris ditulis dengan cara…", options: ["Diapit tanda petik dua", "Ditulis menjorok ke dalam tanpa tanda petik", "Ditulis miring tanpa mencantumkan sumber", "Digabung dengan kalimat penulis"], answer: 1, solution: "1. Kutipan yang panjang dipisahkan menjadi paragraf tersendiri. 2. Paragraf tersebut ditulis menjorok ke dalam. 3. Bentuk menjorok tanpa tanda petik sudah menandai kutipan panjang." },
{ q: "Penulisan daftar pustaka format APA untuk buku dengan dua pengarang yang tepat adalah…", options: ["\"Rina Hartono dan Budi Santoso (2021). Statistik Dasar. Jakarta: Erlangga.\"", "\"Hartono, R., & Santoso, B. (2021). Statistik dasar. Jakarta: Erlangga.\"", "\"Hartono, R. dan Santoso, B., 2021, Statistik Dasar, Erlangga.\"", "\"Statistik Dasar. Hartono & Santoso. 2021.\""], answer: 1, solution: "1. Nama belakang kedua pengarang ditulis dengan inisial nama depan. 2. Kedua nama dihubungkan dengan tanda \"&\". 3. Pola APA dua pengarang: Nama1, Inisial., & Nama2, Inisial. (Tahun). Judul. Kota: Penerbit." },
{ q: "Bagian karya ilmiah yang memuat ringkasan keseluruhan penelitian dalam satu paragraf padat adalah…", options: ["Pendahuluan", "Abstrak", "Daftar pustaka", "Lampiran"], answer: 1, solution: "1. Pembaca membutuhkan gambaran cepat sebelum membaca karya utuh. 2. Gambaran itu disajikan sebagai ringkasan padat satu paragraf di awal. 3. Ringkasan keseluruhan penelitian disebut abstrak." },
{ q: "Hipotesis dalam karya ilmiah merupakan…", options: ["Simpulan akhir penelitian", "Jawaban sementara yang akan diuji kebenarannya", "Daftar alat penelitian", "Saran untuk peneliti lain"], answer: 1, solution: "1. Hipotesis dirumuskan sebelum penelitian dilaksanakan. 2. Ia berupa dugaan yang kebenarannya diuji melalui data. 3. Dugaan sementara yang diuji disebut hipotesis." },
{ q: "Penggunaan tanda petik yang tepat adalah…", options: ["\"Ia berkata: 'saya akan datang.'\"", "\"Ia berkata, \"Saya akan datang.\"\"", "Ia berkata saya akan datang.", "\"Ia berkata, saya akan datang\"."], answer: 1, solution: "1. Kalimat langsung diapit tanda petik dua. 2. Tanda koma memisahkan kalimat pengantar dari petikan langsung. 3. Mengapit petikan langsung adalah fungsi tanda petik dua." },
{ q: "Kalimat berikut yang merupakan pleonasme (pemborosan kata) adalah…", options: ["\"Siswa mengerjakan soal ujian.\"", "\"Mereka turun ke bawah untuk upacara.\"", "\"Guru menjelaskan materi pelajaran.\"", "\"Penelitian ini menggunakan metode survei.\""], answer: 1, solution: "1. Kata \"turun\" sudah mengandung makna \"ke bawah\". 2. Penambahan frasa \"ke bawah\" menjadi berlebih dan mubazir. 3. Pemborosan makna seperti ini disebut pleonasme." },
{ q: "Metode penelitian dalam karya ilmiah dimuat pada bagian…", options: ["Pendahuluan", "Isi/pembahasan", "Penutup", "Daftar pustaka"], answer: 1, solution: "1. Metode menjelaskan cara penelitian dilaksanakan. 2. Uraian cara pelaksanaan termasuk dalam pembahasan isi. 3. Bagian isi memuat landasan teori, metode, dan pembahasan hasil." },
{ q: "Penulisan sumber dari internet dalam daftar pustaka hendaknya mencantumkan…", options: ["Hanya judul artikelnya", "Nama penulis, tahun, judul, dan alamat situs yang diakses", "Nama pemilik warnet", "Harga paket data internet"], answer: 1, solution: "1. Sumber internet tetap memerlukan identitas yang lengkap. 2. Alamat situs memungkinkan pembaca memverifikasi sumber. 3. Nama, tahun, judul, dan alamat situs adalah kelengkapan sumber daring." },
{ q: "Kata penghubung antarkalimat yang tepat untuk mengawali kalimat adalah…", options: ["\"Tetapi ia tetap belajar.\"", "\"Namun, ia tetap belajar.\"", "\"Dan ia tetap belajar.\"", "\"Sehingga ia tetap belajar.\""], answer: 1, solution: "1. Kata \"tetapi\", \"dan\", dan \"sehingga\" adalah penghubung intrakalimat. 2. Penghubung antarkalimat contohnya \"namun\" dan \"oleh karena itu\". 3. Awal kalimat memakai \"Namun,\" yang diikuti tanda koma." },
{ q: "Tujuan penulisan karya ilmiah adalah…", options: ["Menghibur pembaca dengan cerita fiksi", "Menyampaikan gagasan secara sistematis berdasarkan fakta dan kajian", "Mempromosikan produk dagangan", "Menyampaikan opini tanpa data"], answer: 1, solution: "1. Karya ilmiah bersifat faktual, objektif, dan sistematis. 2. Setiap pernyataan didukung data atau hasil kajian. 3. Menyampaikan gagasan sistematis berbasis fakta adalah tujuan karya ilmiah." },
{ q: "\"Penelitian ini dilatarbelakangi oleh rendahnya minat baca siswa.\" Kalimat tersebut tepat dimuat pada bagian…", options: ["Simpulan", "Latar belakang dalam pendahuluan", "Saran", "Abstrak"], answer: 1, solution: "1. Kalimat menjelaskan alasan mengapa penelitian dilakukan. 2. Alasan dilakukannya penelitian disebut latar belakang. 3. Latar belakang dimuat pada bagian pendahuluan." },
{ q: "Penulisan bilangan yang tepat menurut EYD adalah…", options: ["\"Peserta berjumlah 25 orang.\"", "\"Dua puluh lima peserta hadir dalam seminar.\"", "\"Peserta berjumlah dua puluh lima (25) orang.\"", "\"25 peserta hadir.\""], answer: 1, solution: "1. Bilangan pada awal kalimat ditulis dengan huruf, bukan angka. 2. Kalimat diawali \"Dua puluh lima\" sudah memenuhi aturan. 3. Bilangan di awal kalimat ditulis dengan huruf." },
{ q: "Struktur pidato persuasif yang tepat secara berurutan adalah…", options: ["Isi – pembuka – penutup", "Pembuka – isi – penutup", "Penutup – pembuka – isi", "Pembuka – penutup – isi"], answer: 1, solution: "1. Pidato dibuka dengan salam, sapaan, dan pengantar. 2. Dilanjutkan dengan argumen-argumen pada bagian isi. 3. Diakhiri dengan ajakan pada bagian penutup." },
{ q: "\"Assalamu'alaikum, yang saya hormati Bapak Kepala Sekolah…\" Penggalan pidato tersebut termasuk bagian…", options: ["Isi", "Penutup", "Pembuka", "Saran"], answer: 2, solution: "1. Penggalan berisi salam dan sapaan kepada hadirin. 2. Salam dan sapaan selalu mengawali sebuah pidato. 3. Bagian awal pidato disebut pembuka." },
{ q: "\"Kita semua adalah bagian dari sekolah ini, saya pun merasakan keresahan yang sama seperti kalian.\" Metode persuasif yang digunakan adalah…", options: ["Rasionalisasi", "Identifikasi", "Sugesti", "Kompensasi"], answer: 1, solution: "1. Pembicara menyamakan dirinya dengan para pendengar. 2. Kata \"kita\" dan frasa \"sama seperti kalian\" menunjukkan kesamaan posisi. 3. Menyamakan diri dengan audiens disebut metode identifikasi." },
{ q: "\"Data menunjukkan 70% sampah sekolah adalah plastik, karena itu kita harus mengurangi penggunaannya.\" Metode persuasif pada kalimat tersebut adalah…", options: ["Sugesti", "Identifikasi", "Rasionalisasi", "Imitasi"], answer: 2, solution: "1. Ada data angka yang dijadikan bukti. 2. Ajakan didasarkan pada alasan yang logis. 3. Mempengaruhi pendengar lewat alasan logis disebut rasionalisasi." },
{ q: "\"Percayalah, program ini pasti berhasil tanpa perlu banyak bertanya.\" Metode persuasif pada kalimat tersebut adalah…", options: ["Rasionalisasi", "Identifikasi", "Sugesti", "Argumentasi"], answer: 2, solution: "1. Tidak ada data atau alasan logis yang dikemukakan. 2. Pendengar diminta percaya begitu saja pada pembicara. 3. Mempengaruhi tanpa dasar logis disebut sugesti." },
{ q: "Intonasi yang tepat saat menyampaikan bagian ajakan dalam pidato persuasif adalah…", options: ["Datar dan pelan sepanjang pidato", "Tegas dan bersemangat dengan penekanan", "Berbisik agar terdengar misterius", "Tergesa-gesa agar cepat selesai"], answer: 1, solution: "1. Bagian ajakan membutuhkan penekanan agar menggugah pendengar. 2. Nada tegas dan bersemangat menularkan antusiasme. 3. Intonasi ajakan yang tepat adalah tegas dan bersemangat." },
{ q: "Bahasa tubuh yang mendukung keberhasilan pidato persuasif adalah…", options: ["Menunduk terus tanpa kontak mata", "Kontak mata, gestur tangan wajar, dan postur tegap", "Bersandar santai sambil bermain ponsel", "Berbalik membelakangi pendengar"], answer: 1, solution: "1. Kontak mata membangun kedekatan dengan pendengar. 2. Gestur tangan yang wajar memperkuat pesan yang disampaikan. 3. Postur tegap menunjukkan keyakinan pembicara." },
{ q: "Kalimat ajakan yang tepat dalam pidato persuasif adalah…", options: ["\"Saya perintahkan kalian semua diam.\"", "\"Marilah kita jaga kebersihan sekolah mulai hari ini.\"", "\"Terserah kalian mau berbuat apa.\"", "\"Saya tidak peduli pendapat kalian.\""], answer: 1, solution: "1. Kalimat memakai kata ajakan \"marilah\". 2. Kata \"kita\" bersifat inklusif dan tidak memaksa. 3. Ajakan persuasif yang tepat memakai pola \"marilah kita…\"." },
{ q: "Bagian penutup pidato persuasif umumnya berisi…", options: ["Salam pembuka dan perkenalan diri", "Simpulan, ajakan bertindak, harapan, dan terima kasih", "Data statistik yang panjang", "Daftar riwayat hidup pembicara"], answer: 1, solution: "1. Penutup merangkum kembali pesan pokok pidato. 2. Ajakan bertindak adalah inti dari pidato persuasif. 3. Simpulan, ajakan, harapan, dan terima kasih adalah isi penutup." },
{ q: "Ciri bahasa pidato persuasif adalah…", options: ["Kaku, datar, dan penuh istilah teknis", "Emotif, mengajak, dan mudah dipahami pendengar", "Berbelit-belit dan ambigu", "Hanya berisi perintah yang keras"], answer: 1, solution: "1. Tujuan persuasif adalah menggerakkan hati dan tindakan pendengar. 2. Bahasa yang emotif dan mengajak menyentuh perasaan. 3. Bahasa harus mudah dipahami agar pesan sampai." },
{ q: "Urutan bagian surat lamaran pekerjaan yang tepat adalah…", options: ["Isi – tanggal – salam pembuka – tanda tangan", "Tempat dan tanggal – lampiran – perihal – alamat tujuan – salam pembuka – isi – penutup – tanda tangan", "Tanda tangan – isi – tanggal – alamat", "Perihal – tanda tangan – isi – tanggal"], answer: 1, solution: "1. Surat dibuka dengan tempat dan tanggal penulisan. 2. Dilanjutkan lampiran, perihal, dan alamat tujuan. 3. Diakhiri salam pembuka, isi, penutup, dan tanda tangan." },
{ q: "Alinea pembuka surat lamaran pekerjaan umumnya berisi…", options: ["Riwayat pendidikan secara rinci", "Sumber informasi lowongan dan maksud melamar", "Daftar gaji yang diinginkan", "Kritik terhadap perusahaan"], answer: 1, solution: "1. Pembuka menjelaskan dari mana informasi lowongan diperoleh. 2. Dilanjutkan dengan maksud menulis surat tersebut. 3. Sumber informasi dan maksud melamar adalah isi alinea pembuka." },
{ q: "Bahasa yang baik untuk surat dinas adalah bahasa yang…", options: ["Baku, lugas, jelas, dan efektif", "Santun berlebihan dengan banyak basa-basi", "Campuran bahasa gaul agar akrab", "Penuh singkatan tanpa penjelasan"], answer: 0, solution: "1. Surat dinas bersifat resmi dan formal. 2. Bahasa baku menjaga kewibawaan surat. 3. Bahasa yang lugas dan efektif membuat maksud cepat dipahami." },
{ q: "Perbedaan surat dinas dan surat pribadi terletak pada…", options: ["Surat dinas memakai bahasa resmi dan format baku, surat pribadi lebih bebas", "Surat pribadi selalu lebih panjang", "Surat dinas tidak perlu tanda tangan", "Keduanya tidak memiliki perbedaan"], answer: 0, solution: "1. Surat dinas terikat aturan format dan bahasa resmi. 2. Surat pribadi ditulis bebas mengikuti selera penulis. 3. Keterikatan pada format dan bahasa resmi adalah pembeda utamanya." },
{ q: "Fungsi kop surat pada surat dinas adalah…", options: ["Hiasan agar surat terlihat menarik", "Menunjukkan identitas instansi pengirim", "Menggantikan tanda tangan", "Tempat menulis isi surat"], answer: 1, solution: "1. Kop memuat nama, alamat, dan identitas instansi. 2. Penerima langsung mengetahui asal surat. 3. Menunjukkan identitas instansi adalah fungsi kop surat." },
{ q: "Penulisan alamat tujuan surat dinas yang tepat adalah…", options: ["\"Kepada Yth. Bapak Direktur di tempat.\"", "\"Yth. Bapak Direktur PT Maju Jaya di Jakarta.\"", "\"Kepada yang terhormat Bapak Direktur yang baik hati.\"", "\"Untuk Bapak Direktur saja.\""], answer: 1, solution: "1. Kata \"Yth.\" tidak didahului kata \"kepada\". 2. Alamat menyebut jabatan dan instansi dengan jelas. 3. Tanpa kata \"kepada\" setelah \"Yth.\" adalah aturan yang tepat." },
{ q: "Bagian \"Lampiran: 3 lembar\" dan \"Perihal: Lamaran Pekerjaan\" dalam surat lamaran berfungsi…", options: ["Pengganti isi surat", "Memberi tahu jumlah lampiran dan pokok surat kepada penerima", "Hiasan pembuka surat", "Menggantikan tanda tangan"], answer: 1, solution: "1. Lampiran menginformasikan dokumen yang disertakan bersama surat. 2. Perihal menyatakan pokok atau inti surat. 3. Keduanya memberi gambaran awal tentang isi surat." },
{ q: "Kalimat penutup surat lamaran pekerjaan yang tepat adalah…", options: ["\"Demikian surat ini saya buat, atas perhatiannya saya ucapkan terima kasih.\"", "\"Pokoknya saya harus diterima.\"", "\"Terserah Bapak mau menerima atau tidak.\"", "\"Saya tunggu kabar baiknya secepatnya ya.\""], answer: 0, solution: "1. Kalimat santun dan sesuai etika surat resmi. 2. Ada ucapan terima kasih atas perhatian penerima. 3. Penutup yang santun mencerminkan etika pelamar." },
{ q: "Tembusan (cc) dalam surat dinas berfungsi untuk…", options: ["Menyembunyikan surat dari atasan", "Memberitahukan pihak lain yang terkait dengan isi surat", "Menggandakan tanda tangan", "Menghapus arsip surat"], answer: 1, solution: "1. Tembusan dikirim kepada pihak selain penerima utama. 2. Pihak tersebut perlu mengetahui isi surat. 3. Memberitahu pihak yang terkait adalah fungsi tembusan." },
{ q: "Isi surat lamaran pekerjaan pada bagian identitas diri hendaknya memuat…", options: ["Nama, tempat tanggal lahir, pendidikan terakhir, dan keterampilan", "Nama panggilan dan hobi masa kecil", "Curahan perasaan pribadi", "Rahasia keluarga"], answer: 0, solution: "1. Perusahaan membutuhkan data diri yang relevan dengan pekerjaan. 2. Pendidikan terakhir dan keterampilan menjadi bahan pertimbangan. 3. Data diri yang relevan adalah isi bagian identitas diri." }

  ]
};
